            UndertowLogger.REQUEST_IO_LOGGER.ioException((IOException) e);
        } else {
            UndertowLogger.REQUEST_IO_LOGGER.ioException(new IOException(e));
        }
        IoUtils.safeClose(connection);
        IoUtils.safeClose(additional);

