        when(connectionSourceChannel.getConduit()).thenReturn(mock(StreamSourceConduit.class));
        when(connectionSourceChannel.isOpen()).thenReturn(false);
        when(connectionSinkChannel.getConduit()).thenReturn(mock(StreamSinkConduit.class));
