    void malformedResponseFailsTheCurrentRequestAndClosesConnection() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        installCurrentRequest(Methods.GET, callback);
        stubReads(channel, "NOT-A-HTTP-RESPONSE\r\n\r\n");

