    @Test
    void switchingProtocolsWithoutSentRequestDataOnlyRecordsUpgrade() throws Exception {
        HttpResponseBuilder pending = installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
