/**
 * Unit tests for {@link HttpClientConnection.ClientReadListener#handleEvent(StreamSourceChannel)}.
 */
class HttpClientConnectionHandleEventTests {

    private StreamConnection streamConnection;
    private ConduitStreamSourceChannel connectionSourceChannel;
    private ConduitStreamSinkChannel connectionSinkChannel;
    private StreamSourceChannel channel;
    private ChannelListener.SimpleSetter<StreamSourceChannel> readSetter;
    private TrackingByteBufferPool bufferPool;
    private HttpClientConnection connection;
    private HttpClientConnection.ClientReadListener listener;

    @BeforeEach
    void setUp() throws Exception {
        streamConnection = mock(StreamConnection.class);
        connectionSourceChannel = mock(ConduitStreamSourceChannel.class);
        connectionSinkChannel = mock(ConduitStreamSinkChannel.class);
        channel = mock(StreamSourceChannel.class);
        readSetter = new ChannelListener.SimpleSetter<>();
        bufferPool = new TrackingByteBufferPool();

        when(streamConnection.getSourceChannel()).thenReturn(connectionSourceChannel);
        when(streamConnection.getSinkChannel()).thenReturn(connectionSinkChannel);
        when(streamConnection.getCloseSetter()).thenReturn(new ChannelListener.SimpleSetter<StreamConnection>());
        when(streamConnection.getPeerAddress()).thenReturn(new InetSocketAddress("127.0.0.1", 8080));
        when(streamConnection.isOpen()).thenReturn(true);
        when(connectionSourceChannel.getConduit()).thenReturn(mock(StreamSourceConduit.class));
        when(connectionSourceChannel.isOpen()).thenReturn(false);
        when(connectionSinkChannel.getConduit()).thenReturn(mock(StreamSinkConduit.class));
        when(connectionSinkChannel.flush()).thenReturn(true);
        when(channel.getReadSetter()).thenReturn(readSetter);
        when(channel.isReadResumed()).thenReturn(false);

        connection = new HttpClientConnection(streamConnection, OptionMap.EMPTY, bufferPool);
        listener = getField(connection, "clientReadListener");
    }

    @Test
    void noPendingResponseAndSpuriousNotificationDoesNothing() throws Exception {
        stubReads(channel, 0);

        listener.handleEvent(channel);

        assertNull(getField(connection, "pendingResponse"));
        assertNull(getField(connection, "currentRequest"));
        assertTrue(connection.isOpen());
        verify(streamConnection, never()).close();
        verify(channel, never()).suspendReads();
        assertEquals(1, bufferPool.allocated.size());
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void noPendingResponseAndEndOfStreamClosesConnection() throws Exception {
        stubReads(channel, -1);

        listener.handleEvent(channel);

        verify(streamConnection).close();
        assertTrue((state() & stateFlag("CLOSED")) != 0);
        assertFalse(connection.isOpen());
        assertEquals(1, bufferPool.allocated.size());
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void noPendingResponseAndUnexpectedDataClosesConnection() throws Exception {
        stubReads(channel, "unexpected bytes");

        listener.handleEvent(channel);

        verify(streamConnection).close();
        assertTrue((state() & stateFlag("CLOSED")) != 0);
        assertFalse(connection.isOpen());
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void noPendingResponseAndIoExceptionClosesUnderlyingConnection() throws Exception {
        IOException readFailure = new IOException("read failed");
        stubReads(channel, readFailure);

        listener.handleEvent(channel);

        verify(streamConnection).close();
        assertEquals(1, bufferPool.allocated.size());
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void zeroReadWithoutResumedReadsInstallsReadListener() throws Exception {
        HttpResponseBuilder pending = installPendingResponse();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, null);
        stubReads(channel, 0);

        listener.handleEvent(channel);

        assertSame(listener, readSetter.get());
        verify(channel).resumeReads();
        verify(channel, never()).suspendReads();
        assertSame(pending, getField(connection, "pendingResponse"));
        assertSame(exchange, getField(connection, "currentRequest"));
        assertNull(exchange.getResponse());
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void zeroReadWithAlreadyResumedReadsDoesNotInstallListener() throws Exception {
        when(channel.isReadResumed()).thenReturn(true);
        HttpResponseBuilder pending = installPendingResponse();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, null);
        stubReads(channel, 0);

        listener.handleEvent(channel);

        verify(channel, never()).getReadSetter();
        verify(channel, never()).resumeReads();
        assertNull(readSetter.get());
        assertSame(pending, getField(connection, "pendingResponse"));
        assertSame(exchange, getField(connection, "currentRequest"));
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void incompleteResponseIsRetainedForTheNextRead() throws Exception {
        HttpResponseBuilder pending = installPendingResponse();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, null);
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        exchange.setResponseListener(callback);
        stubReads(channel, "HTTP/1.1 200 OK\r\nContent-Le", 0);

        listener.handleEvent(channel);

        assertSame(pending, getField(connection, "pendingResponse"));
        assertFalse(pending.getParseState().isComplete());
        assertEquals(Protocols.HTTP_1_1, pending.getProtocol());
        assertEquals(200, pending.getStatusCode());
        assertNull(exchange.getResponse());
        assertEquals(0, callback.completedCount);
        assertSame(listener, readSetter.get());
        verify(channel).resumeReads();
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void completeResponseIsDeliveredAndResponseChannelIsPrepared() throws Exception {
        HttpResponseBuilder pending = installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
        stubReads(channel, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\nX-Test: value\r\n\r\n");

        listener.handleEvent(channel);

        assertEquals(1, callback.completedCount);
        assertSame(exchange, callback.completed);
        assertNotNull(exchange.getResponse());
        ClientResponse response = exchange.getResponse();
        assertEquals(200, response.getResponseCode());
        assertEquals("OK", response.getStatus());
        assertEquals(Protocols.HTTP_1_1, response.getProtocol());
        assertEquals("value", response.getResponseHeaders().getFirst(new HttpString("X-Test")));
        assertTrue(pending.getParseState().isComplete());
        assertNull(getField(connection, "pendingResponse"));
        assertSame(exchange, getField(connection, "currentRequest"));
        verify(channel).suspendReads();
        assertNull(readSetter.get());
        ArgumentCaptor<StreamSourceConduit> conduit = ArgumentCaptor.forClass(StreamSourceConduit.class);
        verify(connectionSourceChannel, times(2)).setConduit(conduit.capture());
        assertInstanceOf(FixedLengthStreamSourceConduit.class, conduit.getAllValues().get(1));
        assertTrue(connection.isOpen());
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void responseWithConnectionCloseMarksConnectionAndFailsQueuedExchanges() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback currentCallback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, currentCallback);
        HttpClientExchange queued = new HttpClientExchange(null,
                new ClientRequest().setMethod(Methods.GET).setPath("/queued").setProtocol(Protocols.HTTP_1_1),
                connection);
        CapturingExchangeCallback queuedCallback = new CapturingExchangeCallback();
        queued.setResponseListener(queuedCallback);
        getPendingQueue().add(queued);
        stubReads(channel, "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Length: 0\r\n\r\n");

        listener.handleEvent(channel);

        assertEquals(1, currentCallback.completedCount);
        assertSame(exchange, currentCallback.completed);
        assertEquals(1, queuedCallback.failedCount);
        assertNotNull(queuedCallback.failure);
        assertTrue(getPendingQueue().isEmpty());
        assertTrue((state() & stateFlag("CLOSE_REQ")) != 0);
        assertFalse(connection.isOpen());
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void continueResponseBuildsANewPendingResponse() throws Exception {
        HttpResponseBuilder originalPending = installPendingResponse();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, null);
        stubReads(channel, "HTTP/1.1 100 Continue\r\n\r\n");

        listener.handleEvent(channel);

        assertNotNull(exchange.getContinueResponse());
        assertEquals(100, exchange.getContinueResponse().getResponseCode());
        assertNull(exchange.getResponse());
        HttpResponseBuilder replacement = getField(connection, "pendingResponse");
        assertNotNull(replacement);
        assertFalse(originalPending == replacement);
        assertFalse(replacement.getParseState().isComplete());
        verify(channel, never()).suspendReads();
        assertNull(readSetter.get());
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void endOfStreamWhileResponsePendingFailsTheCurrentRequest() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
        exchange.setResponseListener(callback);
        stubReads(channel, -1);

        listener.handleEvent(channel);

        assertEquals(1, callback.failedCount);
        assertNotNull(callback.failure);
        assertNull(getField(connection, "currentRequest"));
        assertNull(getField(connection, "pendingResponse"));
        verify(channel).suspendReads();
        verify(streamConnection).close();
        assertTrue((state() & stateFlag("CLOSED")) != 0);
        assertFalse(connection.isOpen());
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void ioExceptionWhileResponsePendingFailsRequestAndClosesBothChannels() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        installCurrentRequest(Methods.GET, callback);
        IOException readFailure = new IOException("connection reset");
        stubReads(channel, readFailure);

        listener.handleEvent(channel);

        assertEquals(1, callback.failedCount);
        assertSame(readFailure, callback.failure);
        assertNull(getField(connection, "currentRequest"));
        assertNull(getField(connection, "pendingResponse"));
        verify(channel).close();
        verify(streamConnection).close();
        assertTrue(bufferPool.allocated.get(0).closed);
        assertNull(getField(connection, "pooledBuffer"));
    }

    @Test
    void malformedResponseFailsTheCurrentRequestAndClosesConnection() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        installCurrentRequest(Methods.GET, callback);
        stubReads(channel, "NOT-A-HTTP-RESPONSE\r\n\r\n");

        listener.handleEvent(channel);

        assertEquals(1, callback.failedCount);
        assertNotNull(callback.failure);
        assertNotNull(callback.failure.getCause());
        verify(streamConnection).close();
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void switchingProtocolsWithoutSentRequestDataOnlyRecordsUpgrade() throws Exception {
        HttpResponseBuilder pending = installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
        stubReads(channel, "HTTP/1.1 101 Switching Protocols\r\nUpgrade: h2c\r\nConnection: Upgrade\r\n\r\n");

        listener.handleEvent(channel);

        assertTrue((Boolean) getField(connection, "http2UpgradeReceived"));
        assertNull(exchange.getResponse());
        assertEquals(0, callback.completedCount);
        assertSame(pending, getField(connection, "pendingResponse"));
        verify(channel, never()).suspendReads();
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void expectationFailedResponseClosesConnectionAndTerminatesRequest() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
        exchange.getRequest().getRequestHeaders().put(Headers.EXPECT, "100-continue");
        stubReads(channel, "HTTP/1.1 417 Expectation Failed\r\nContent-Length: 0\r\n\r\n");

        listener.handleEvent(channel);

        assertEquals(1, callback.completedCount);
        assertNotNull(exchange.getResponse());
        assertEquals(417, exchange.getResponse().getResponseCode());
        verify(connectionSinkChannel).shutdownWrites();
        assertTrue(exchange.isRequestDataSent());
        assertTrue((state() & stateFlag("CLOSE_REQ")) != 0);
        assertFalse(connection.isOpen());
        assertTrue(bufferPool.allocated.get(0).closed);
    }

    @Test
    void trailingDataAfterResponseIsPushedBackAndBufferIsRetained() throws Exception {
        installPendingResponse();
        CapturingExchangeCallback callback = new CapturingExchangeCallback();
        HttpClientExchange exchange = installCurrentRequest(Methods.GET, callback);
        stubReads(channel, "HTTP/1.1 200 OK\r\nContent-Length: 0\r\n\r\nEXTRA");

        listener.handleEvent(channel);

        assertEquals(1, callback.completedCount);
        assertNotNull(exchange.getResponse());
        TrackingPooledByteBuffer allocated = bufferPool.allocated.get(0);
        assertEquals(0, allocated.closeCount);
        assertTrue(allocated.isOpen());
        Object retained = getField(connection, "pooledBuffer");
        assertInstanceOf(PooledAdaptor.class, retained);
        assertSame(allocated.getBuffer(), ((PooledAdaptor) retained).getResource());
        verify(channel).suspendReads();
    }

    private int state() throws Exception {
        return getField(connection, "state");
    }

    private static int stateFlag(String name) throws Exception {
        Field field = HttpClientConnection.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.getInt(null);
    }

    private HttpResponseBuilder installPendingResponse() throws Exception {
        HttpResponseBuilder builder = new HttpResponseBuilder();
        setField(connection, "pendingResponse", builder);
        return builder;
    }

    private HttpClientExchange installCurrentRequest(HttpString method, ClientCallback<ClientExchange> callback) throws Exception {
        ClientRequest request = new ClientRequest()
                .setMethod(method)
                .setPath("/")
                .setProtocol(Protocols.HTTP_1_1);
        HttpClientExchange exchange = new HttpClientExchange(null, request, connection);
        if (callback != null) {
            exchange.setResponseListener(callback);
        }
        setField(connection, "currentRequest", exchange);
        return exchange;
    }

    @SuppressWarnings("unchecked")
    private Deque<HttpClientExchange> getPendingQueue() throws Exception {
        return (Deque<HttpClientExchange>) getField(connection, "pendingQueue");
    }

    private static void stubReads(StreamSourceChannel channel, Object... results) throws IOException {
        AtomicInteger index = new AtomicInteger();
        when(channel.read(any(ByteBuffer.class))).thenAnswer(invocation -> {
            int current = index.getAndIncrement();
            if (current >= results.length) {
                throw new AssertionError("Unexpected additional read invocation");
            }
            Object result = results[current];
            if (result instanceof Integer) {
                return result;
            }
            if (result instanceof IOException) {
                throw (IOException) result;
            }
            byte[] bytes = ((String) result).getBytes(StandardCharsets.ISO_8859_1);
            ByteBuffer buffer = invocation.getArgument(0);
            buffer.put(bytes);
            return bytes.length;
        });
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(Object target, String name) throws Exception {
        Field field = findField(target.getClass(), name);
        field.setAccessible(true);
        return (T) field.get(target);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = findField(target.getClass(), name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Field findField(Class<?> type, String name) throws NoSuchFieldException {
        Class<?> current = type;
        while (current != null) {
            try {
                return current.getDeclaredField(name);
            } catch (NoSuchFieldException ignored) {
                current = current.getSuperclass();
            }
        }
        throw new NoSuchFieldException(name);
    }

    private static final class CapturingExchangeCallback implements ClientCallback<ClientExchange> {
        private ClientExchange completed;
        private IOException failure;
        private int completedCount;
        private int failedCount;

        @Override
        public void completed(ClientExchange result) {
            completedCount++;
            completed = result;
        }

        @Override
        public void failed(IOException e) {
            failedCount++;
            failure = e;
        }
    }

    private static final class TrackingByteBufferPool implements ByteBufferPool {
        private final List<TrackingPooledByteBuffer> allocated = new ArrayList<>();

        @Override
        public PooledByteBuffer allocate() {
            TrackingPooledByteBuffer buffer = new TrackingPooledByteBuffer();
            allocated.add(buffer);
            return buffer;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return TrackingPooledByteBuffer.CAPACITY;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static final class TrackingPooledByteBuffer implements PooledByteBuffer {
        private static final int CAPACITY = 8192;

        private final ByteBuffer buffer = ByteBuffer.allocate(CAPACITY);
        private boolean open = true;
        private int closeCount;

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            closeCount++;
            open = false;
        }

        @Override
        public boolean isOpen() {
            return open;
        }
    }
}
