        if (!frame.isAck()) {
            //server side ping, return it
            frame.getHttp2Channel().sendPing(id);
        } else {
            PingListener listener = outstandingPings.remove(new PingKey(id));
            if(listener != null) {
                listener.acknowledged();
            }
        }
    }

