    @Test
    void finalResponseCompletesMatchingExchange() throws Exception {
        Http2StreamSourceChannel response = responseStream(1, "200");
        expect(channel.receive()).andReturn(response);
        Http2ClientConnection connection = newConnection();

        Http2ClientExchange exchange = new Http2ClientExchange(connection, null, new ClientRequest());
        ClientCallback<ClientExchange> callback = createMock(ClientCallback.class);
        callback.completed(exchange);
        expectLastCall().once();
        exchange.setResponseListener(callback);
        currentExchanges(connection).put(1, exchange);

        replay(response);
        replay(callback);

        receiveListener().handleEvent(channel);

        ClientResponse clientResponse = exchange.getResponse();
        assertNotNull(clientResponse);
        assertEquals(200, clientResponse.getResponseCode());
        assertSame(response, exchange.getResponseChannel());
        verify(response);
        verify(callback);
    }

