        return handshakeSetter;
    }

    @Override
    protected void notifyWriteClosed() {
        try {
            sslConduit.notifyWriteClosed();
        } finally {
            super.notifyWriteClosed();
        }
    }

    @Override
    protected void notifyReadClosed() {
        try {
            sslConduit.notifyReadClosed();
        } finally {
            super.notifyReadClosed();
        }
