 */
class UndertowAcceptingSslChannelAcceptTests {

    private static final String PEER_HOST = "peer.example";
    private static final int PEER_PORT = 43210;
    private static final InetSocketAddress PEER_ADDRESS = InetSocketAddress.createUnresolved(PEER_HOST, PEER_PORT);

    private AcceptingChannel<StreamConnection> tcpServer;
    private SSLContext sslContext;
    private TestStreamConnection tcpConnection;

    @BeforeEach
    void setUp() throws Exception {
        @SuppressWarnings("unchecked")
        AcceptingChannel<StreamConnection> mock = createMock(AcceptingChannel.class);
        tcpServer = mock;
        sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, null, null);
        tcpConnection = new TestStreamConnection(PEER_ADDRESS);
    }

    @Test
    void acceptReturnsNullWhenThereIsNoPendingConnection() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, null);

        UndertowSslConnection result = channel.accept();

        assertNull(result);
        assertNull(channel.acceptedTcpConnection);
        assertNull(channel.acceptedEngine);
        verify(tcpServer);
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptConfiguresClientModeSessionCreationAndCipherSuiteOrder() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_USE_CLIENT_MODE, true)
                .set(Options.SSL_ENABLE_SESSION_CREATION, false)
                .set(UndertowOptions.SSL_USER_CIPHER_SUITES_ORDER, true)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertSame(channel.acceptedConnection, result);
        assertSame(tcpConnection, channel.acceptedTcpConnection);
        SSLEngine engine = channel.acceptedEngine;
        assertTrue(engine.getUseClientMode());
        assertFalse(engine.getEnableSessionCreation());
        assertTrue(engine.getSSLParameters().getUseCipherSuitesOrder());
        assertEquals(PEER_HOST, engine.getPeerHost());
        assertEquals(PEER_PORT, engine.getPeerPort());
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptUsesSecureDefaultsForAServerConnection() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, tcpConnection);

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertSame(channel.acceptedConnection, result);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertTrue(engine.getEnableSessionCreation());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
        assertFalse(engine.getSSLParameters().getUseCipherSuitesOrder());
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptDisablesClientAuthWhenNotRequested() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.NOT_REQUESTED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
    }

    @Test
    void acceptRequestsClientAuthWhenConfigured() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUESTED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertTrue(engine.getWantClientAuth());
    }

    @Test
    void acceptRequiresClientAuthWhenConfigured() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUIRED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertTrue(engine.getNeedClientAuth());
    }

    @Test
    void acceptDoesNotApplyServerClientAuthInClientMode() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUIRED)
                .set(Options.SSL_USE_CLIENT_MODE, true)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertTrue(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
    }

    @Test
    void acceptFiltersConfiguredCipherSuitesAndProtocolsAgainstEngineSupport() throws Exception {
        String supportedCipher = sslContext.getSupportedSSLParameters().getCipherSuites()[0];
        String supportedProtocol = sslContext.getSupportedSSLParameters().getProtocols()[0];
        String unsupportedCipher = "UNDERTOW_TEST_UNSUPPORTED_CIPHER";
