    private CapturingAcceptingSslChannel newChannel(OptionMap options, StreamConnection acceptedConnection) {
        return newChannel(sslContext, options, acceptedConnection);
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    private CapturingAcceptingSslChannel newChannel(SSLContext context, OptionMap options,
                                                    StreamConnection acceptedConnection) {
        ChannelListener.Setter closeSetter = new ChannelListener.SimpleSetter();
        ChannelListener.Setter acceptSetter = new ChannelListener.SimpleSetter();
        expect(tcpServer.getCloseSetter()).andReturn(closeSetter);
        expect(tcpServer.getAcceptSetter()).andReturn(acceptSetter);
        UndertowXnioSsl ssl = new UndertowXnioSsl(null, OptionMap.EMPTY, context);
        CapturingAcceptingSslChannel channel = new CapturingAcceptingSslChannel(ssl, tcpServer, options, null, false);
        expect(tcpServer.accept()).andReturn(acceptedConnection);
        replay(tcpServer);
        return channel;
    }

    private static SSLContext contextReturning(final SSLEngine engine) {
        return new SSLContext(new SSLContextSpi() {
            @Override
            protected void engineInit(KeyManager[] keyManagers, TrustManager[] trustManagers, SecureRandom secureRandom) {
            }

            @Override
            protected SSLSocketFactory engineGetSocketFactory() {
                return null;
            }

            @Override
            protected SSLServerSocketFactory engineGetServerSocketFactory() {
                return null;
            }

            @Override
            protected SSLEngine engineCreateSSLEngine() {
                return engine;
            }

            @Override
            protected SSLEngine engineCreateSSLEngine(String host, int port) {
                return engine;
            }

            @Override
            protected SSLSessionContext engineGetServerSessionContext() {
                return null;
            }

            @Override
            protected SSLSessionContext engineGetClientSessionContext() {
                return null;
            }
        }, null, "test") {
        };
    }

    private static final class CapturingAcceptingSslChannel extends UndertowAcceptingSslChannel {

        private final UndertowSslConnection acceptedConnection = createNiceMock(UndertowSslConnection.class);
        private StreamConnection acceptedTcpConnection;
        private SSLEngine acceptedEngine;
        private IOException acceptIOException;
        private RuntimeException acceptRuntimeException;

        private CapturingAcceptingSslChannel(UndertowXnioSsl ssl, AcceptingChannel<? extends StreamConnection> tcpServer,
                                             OptionMap optionMap, io.undertow.connector.ByteBufferPool bufferPool,
                                             boolean startTls) {
            super(ssl, tcpServer, optionMap, bufferPool, startTls);
        }

        @Override
        protected UndertowSslConnection accept(StreamConnection tcpServer, SSLEngine sslEngine) throws IOException {
            this.acceptedTcpConnection = tcpServer;
            this.acceptedEngine = sslEngine;
            if (acceptIOException != null) {
                throw acceptIOException;
            }
            if (acceptRuntimeException != null) {
                throw acceptRuntimeException;
            }
            return acceptedConnection;
        }
    }

    private static final class TestStreamConnection extends StreamConnection {

        private final InetSocketAddress peerAddress;
        private volatile boolean closed;

        private TestStreamConnection(InetSocketAddress peerAddress) {
            super(null);
