import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.SocketAddress;
import java.security.SecureRandom;

import javax.net.ssl.KeyManager;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLContextSpi;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.SSLServerSocketFactory;
import javax.net.ssl.SSLSessionContext;
import javax.net.ssl.SSLSocketFactory;
import javax.net.ssl.TrustManager;

import io.undertow.UndertowOptions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.ChannelListener;
import org.xnio.OptionMap;
import org.xnio.Options;
import org.xnio.Sequence;
import org.xnio.SslClientAuthMode;
import org.xnio.StreamConnection;
import org.xnio.channels.AcceptingChannel;

/**
 * Unit tests for {@link UndertowAcceptingSslChannel#accept()}.
 */
class UndertowAcceptingSslChannelAcceptTests {

    private static final String PEER_HOST = "peer.example";
    private static final int PEER_PORT = 43210;
    private static final InetSocketAddress PEER_ADDRESS = InetSocketAddress.createUnresolved(PEER_HOST, PEER_PORT);

    private AcceptingChannel<StreamConnection> tcpServer;
    private SSLContext sslContext;
    private TestStreamConnection tcpConnection;

    @BeforeEach
    void setUp() throws Exception {
        @SuppressWarnings("unchecked")
        AcceptingChannel<StreamConnection> mock = createMock(AcceptingChannel.class);
        tcpServer = mock;
        sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, null, null);
        tcpConnection = new TestStreamConnection(PEER_ADDRESS);
    }

    @Test
    void acceptReturnsNullWhenThereIsNoPendingConnection() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, null);

        UndertowSslConnection result = channel.accept();

        assertNull(result);
        assertNull(channel.acceptedTcpConnection);
        assertNull(channel.acceptedEngine);
        verify(tcpServer);
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptPropagatesIOExceptionFromTcpServerWithoutCreatingAnSslConnection() throws Exception {
        @SuppressWarnings({"rawtypes", "unchecked"})
        ChannelListener.Setter closeSetter = new ChannelListener.SimpleSetter();
        @SuppressWarnings({"rawtypes", "unchecked"})
        ChannelListener.Setter acceptSetter = new ChannelListener.SimpleSetter();
        expect(tcpServer.getCloseSetter()).andReturn(closeSetter);
        expect(tcpServer.getAcceptSetter()).andReturn(acceptSetter);
        IOException failure = new IOException("tcp accept failed");
        expect(tcpServer.accept()).andThrow(failure);
        replay(tcpServer);
        UndertowXnioSsl ssl = new UndertowXnioSsl(null, OptionMap.EMPTY, sslContext);
        CapturingAcceptingSslChannel channel = new CapturingAcceptingSslChannel(ssl, tcpServer, OptionMap.EMPTY, null, false);

        IOException thrown = assertThrows(IOException.class, channel::accept);

        verify(tcpServer);
        assertSame(failure, thrown);
        assertNull(channel.acceptedTcpConnection);
        assertNull(channel.acceptedEngine);
    }

    @Test
    void acceptConfiguresClientModeSessionCreationAndCipherSuiteOrder() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_USE_CLIENT_MODE, true)
                .set(Options.SSL_ENABLE_SESSION_CREATION, false)
                .set(UndertowOptions.SSL_USER_CIPHER_SUITES_ORDER, true)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertSame(channel.acceptedConnection, result);
        assertSame(tcpConnection, channel.acceptedTcpConnection);
        SSLEngine engine = channel.acceptedEngine;
        assertTrue(engine.getUseClientMode());
        assertFalse(engine.getEnableSessionCreation());
        assertTrue(engine.getSSLParameters().getUseCipherSuitesOrder());
        assertEquals(PEER_HOST, engine.getPeerHost());
        assertEquals(PEER_PORT, engine.getPeerPort());
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptUsesSecureDefaultsForAServerConnection() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, tcpConnection);

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertSame(channel.acceptedConnection, result);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertTrue(engine.getEnableSessionCreation());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
        SSLEngine referenceEngine = sslContext.createSSLEngine(PEER_HOST, PEER_PORT);
        assertEquals(referenceEngine.getSSLParameters().getUseCipherSuitesOrder(),
                engine.getSSLParameters().getUseCipherSuitesOrder());
        assertFalse(tcpConnection.isClosed());
    }

    @Test
    void acceptDisablesClientAuthWhenNotRequested() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.NOT_REQUESTED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
    }

    @Test
    void acceptRequestsClientAuthWhenConfigured() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUESTED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertTrue(engine.getWantClientAuth());
    }

    @Test
    void acceptRequiresClientAuthWhenConfigured() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUIRED)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertFalse(engine.getUseClientMode());
        assertTrue(engine.getNeedClientAuth());
    }

    @Test
    void acceptDoesNotApplyServerClientAuthInClientMode() throws Exception {
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_CLIENT_AUTH_MODE, SslClientAuthMode.REQUIRED)
                .set(Options.SSL_USE_CLIENT_MODE, true)
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertTrue(engine.getUseClientMode());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getNeedClientAuth());
        assertFalse(engine.getWantClientAuth());
    }

    @Test
    void acceptFiltersConfiguredCipherSuitesAndProtocolsAgainstEngineSupport() throws Exception {
        String supportedCipher = sslContext.getSupportedSSLParameters().getCipherSuites()[0];
        String supportedProtocol = sslContext.getSupportedSSLParameters().getProtocols()[0];
        String unsupportedCipher = "UNDERTOW_TEST_UNSUPPORTED_CIPHER";
        String unsupportedProtocol = "UNDERTOW_TEST_UNSUPPORTED_PROTOCOL";
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_ENABLED_CIPHER_SUITES, Sequence.of(supportedCipher, unsupportedCipher))
                .set(Options.SSL_ENABLED_PROTOCOLS, Sequence.of(supportedProtocol, unsupportedProtocol))
                .getMap();
        CapturingAcceptingSslChannel channel = newChannel(options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        SSLEngine engine = channel.acceptedEngine;
        assertArrayEquals(new String[]{supportedCipher}, engine.getEnabledCipherSuites());
        assertArrayEquals(new String[]{supportedProtocol}, engine.getEnabledProtocols());
    }

    @Test
    void acceptUsesConfiguredCipherSuitesAndProtocolsWhenEngineReportsNoSupportedValues() throws Exception {
        SSLEngine engine = createMock(SSLEngine.class);
        engine.setUseClientMode(false);
        engine.setEnableSessionCreation(true);
        expect(engine.getSupportedCipherSuites()).andReturn(new String[0]);
        engine.setEnabledCipherSuites(aryEq(new String[]{"configured-cipher"}));
        expect(engine.getSupportedProtocols()).andReturn(new String[0]);
        engine.setEnabledProtocols(aryEq(new String[]{"configured-protocol"}));
        replay(engine);
        SSLContext context = contextReturning(engine);
        OptionMap options = OptionMap.builder()
                .set(Options.SSL_ENABLED_CIPHER_SUITES, Sequence.of("configured-cipher"))
                .set(Options.SSL_ENABLED_PROTOCOLS, Sequence.of("configured-protocol"))
                .getMap();

        CapturingAcceptingSslChannel channel = newChannel(context, options, tcpConnection);

        channel.accept();

        verify(tcpServer);
        verify(engine);
        assertSame(engine, channel.acceptedEngine);
    }

    @Test
    void acceptClosesTcpConnectionAndReturnsNullWhenAcceptingFailsWithIoException() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, tcpConnection);
        channel.acceptIOException = new IOException("simulated accept failure");

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertNull(result);
        assertTrue(tcpConnection.isClosed());
    }

    @Test
    void acceptClosesTcpConnectionAndReturnsNullWhenAcceptingFailsWithRuntimeException() throws Exception {
        CapturingAcceptingSslChannel channel = newChannel(OptionMap.EMPTY, tcpConnection);
        channel.acceptRuntimeException = new IllegalStateException("simulated accept failure");

        UndertowSslConnection result = channel.accept();

        verify(tcpServer);
        assertNull(result);
        assertTrue(tcpConnection.isClosed());
    }

    private CapturingAcceptingSslChannel newChannel(OptionMap options, StreamConnection acceptedConnection) throws IOException {
        return newChannel(sslContext, options, acceptedConnection);
    }

    @SuppressWarnings({"rawtypes", "unchecked"})
    private CapturingAcceptingSslChannel newChannel(SSLContext context, OptionMap options,
                                                    StreamConnection acceptedConnection) throws IOException {
        ChannelListener.Setter closeSetter = new ChannelListener.SimpleSetter();
        ChannelListener.Setter acceptSetter = new ChannelListener.SimpleSetter();
        expect(tcpServer.getCloseSetter()).andReturn(closeSetter);
        expect(tcpServer.getAcceptSetter()).andReturn(acceptSetter);
        expect(tcpServer.accept()).andReturn(acceptedConnection);
        replay(tcpServer);
        UndertowXnioSsl ssl = new UndertowXnioSsl(null, OptionMap.EMPTY, context);
        return new CapturingAcceptingSslChannel(ssl, tcpServer, options, null, false);
    }

    private static SSLContext contextReturning(final SSLEngine engine) {
        return new SSLContext(new SSLContextSpi() {
            @Override
            protected void engineInit(KeyManager[] keyManagers, TrustManager[] trustManagers, SecureRandom secureRandom) {
            }

            @Override
            protected SSLSocketFactory engineGetSocketFactory() {
                return null;
            }

            @Override
            protected SSLServerSocketFactory engineGetServerSocketFactory() {
                return null;
            }

            @Override
            protected SSLEngine engineCreateSSLEngine() {
                return engine;
            }

            @Override
            protected SSLEngine engineCreateSSLEngine(String host, int port) {
                return engine;
            }

            @Override
            protected SSLSessionContext engineGetServerSessionContext() {
                return null;
            }

            @Override
            protected SSLSessionContext engineGetClientSessionContext() {
                return null;
            }
        }, null, "test") {
        };
    }

    private static final class CapturingAcceptingSslChannel extends UndertowAcceptingSslChannel {

        private final UndertowSslConnection acceptedConnection = createNiceMock(UndertowSslConnection.class);
        private StreamConnection acceptedTcpConnection;
        private SSLEngine acceptedEngine;
        private IOException acceptIOException;
        private RuntimeException acceptRuntimeException;

        private CapturingAcceptingSslChannel(UndertowXnioSsl ssl, AcceptingChannel<? extends StreamConnection> tcpServer,
                                             OptionMap optionMap, io.undertow.connector.ByteBufferPool bufferPool,
                                             boolean startTls) {
            super(ssl, tcpServer, optionMap, bufferPool, startTls);
        }

        @Override
        protected UndertowSslConnection accept(StreamConnection tcpServer, SSLEngine sslEngine) throws IOException {
            this.acceptedTcpConnection = tcpServer;
            this.acceptedEngine = sslEngine;
            if (acceptIOException != null) {
                throw acceptIOException;
            }
            if (acceptRuntimeException != null) {
                throw acceptRuntimeException;
            }
            return acceptedConnection;
        }
    }

    private static final class TestStreamConnection extends StreamConnection {

        private final InetSocketAddress peerAddress;
        private volatile boolean closed;

        private TestStreamConnection(InetSocketAddress peerAddress) {
            super(null);
            this.peerAddress = peerAddress;
        }

        private boolean isClosed() {
            return closed;
        }

        @Override
        protected void closeAction() {
            closed = true;
        }

        @Override
        public SocketAddress getPeerAddress() {
            return peerAddress;
        }

        @Override
        public SocketAddress getLocalAddress() {
            return null;
        }

    }
}
