import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Unit tests for {@link ContentEncodedResourceManager#getResource(Resource, HttpServerExchange)}.
 */
class ContentEncodedResourceManagerGetResourceTests {

    private static final String ENCODING = "gzip";

    /**
     * A trivial encoder that simply forwards the wrapped conduit. This keeps the success path
     * independent of the exchange/crypto machinery that the real gzip encoder needs.
     */
    private static final ContentEncodingProvider PASSTHROUGH_ENCODING =
            () -> (factory, exchange) -> factory.create();

    @TempDir
    Path tempDir;

    private ContentEncodedResourceManager manager;

    @BeforeEach
    void setUp() {
        manager = newManager(0, 0, null, true);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private ContentEncodingRepository repository(boolean encodingEnabled) {
        final ContentEncodingRepository repository = new ContentEncodingRepository();
        repository.addEncodingHandler(ENCODING, PASSTHROUGH_ENCODING, 10,
                encodingEnabled ? Predicates.truePredicate() : Predicates.falsePredicate());
        return repository;
    }

    private ContentEncodedResourceManager newManager(int minSize, int maxSize, Predicate allowed,
            boolean encodingEnabled) {
        return new ContentEncodedResourceManager(tempDir, new TestCachingResourceManager(tempDir),
                repository(encodingEnabled), minSize, maxSize, allowed);
    }

    private static HttpServerExchange exchangeWithAcceptEncoding(String acceptEncoding) {
        final HttpServerExchange exchange = new HttpServerExchange(null);
        if (acceptEncoding != null) {
            exchange.getRequestHeaders().put(Headers.ACCEPT_ENCODING, acceptEncoding);
        }
        return exchange;
    }

    private Path writeSource(String name, String content) throws IOException {
        final Path file = tempDir.resolve(name);
        Files.write(file, content.getBytes(StandardCharsets.UTF_8));
        return file;
    }

    private static Resource resource(String path, Path file, long contentLength) {
        return new TestResource(path, file, contentLength);
    }

    private static String newPath(String path) {
        return path + ".undertow.encoding." + ENCODING;
    }

    @SuppressWarnings("unchecked")
    private static ConcurrentMap<Object, Object> lockMap(ContentEncodedResourceManager manager)
            throws Exception {
        final Field field = ContentEncodedResourceManager.class.getDeclaredField("fileLocks");
        field.setAccessible(true);
        return (ConcurrentMap<Object, Object>) field.get(manager);
    }

    private static Object lockKey(String path, String encoding) throws Exception {
        final Class<?> type = Class.forName(
                "io.undertow.server.handlers.encoding.ContentEncodedResourceManager$LockKey");
        final Constructor<?> constructor = type.getDeclaredConstructor(String.class, String.class);
        constructor.setAccessible(true);
        return constructor.newInstance(path, encoding);
    }

    // ---------------------------------------------------------------------
    // Early exits
    // ---------------------------------------------------------------------

    @Test
    void returnsNullWhenResourceHasNoFile() throws IOException {
        final Resource resource = resource("no-file.txt", null, 10L);

        assertNull(manager.getResource(resource, exchangeWithAcceptEncoding(ENCODING)));
    }

    @Test
    void returnsNullWhenContentLengthIsBelowMinimum() throws IOException {
        manager = newManager(5, 0, null, true);
        final Path file = writeSource("below-min.txt", "abcd");

        assertNull(manager.getResource(resource("below-min.txt", file, 4L),
                exchangeWithAcceptEncoding(ENCODING)));
        assertFalse(Files.exists(tempDir.resolve(newPath("below-min.txt"))));
    }

    @Test
    void succeedsWhenContentLengthEqualsMinimum() throws IOException {
        manager = newManager(5, 0, null, true);
        final Path file = writeSource("at-min.txt", "abcde");

        final ContentEncodedResource result = manager.getResource(
                resource("at-min.txt", file, 5L), exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(ENCODING, result.getContentEncoding());
        assertArrayEquals("abcde".getBytes(StandardCharsets.UTF_8),
                Files.readAllBytes(tempDir.resolve(newPath("at-min.txt"))));
    }

    @Test
    void returnsNullWhenContentLengthIsAboveMaximum() throws IOException {
        manager = newManager(0, 5, null, true);
        final Path file = writeSource("above-max.txt", "abcdef");

        assertNull(manager.getResource(resource("above-max.txt", file, 6L),
                exchangeWithAcceptEncoding(ENCODING)));
        assertFalse(Files.exists(tempDir.resolve(newPath("above-max.txt"))));
    }

    @Test
    void succeedsWhenContentLengthEqualsMaximum() throws IOException {
        manager = newManager(0, 5, null, true);
        final Path file = writeSource("at-max.txt", "abcde");

        final ContentEncodedResource result = manager.getResource(
                resource("at-max.txt", file, 5L), exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(ENCODING, result.getContentEncoding());
        assertArrayEquals("abcde".getBytes(StandardCharsets.UTF_8),
                Files.readAllBytes(tempDir.resolve(newPath("at-max.txt"))));
    }

    @Test
    void returnsNullWhenEncodingPredicateRejectsExchange() throws IOException {
        final AtomicInteger invocations = new AtomicInteger();
        manager = newManager(0, 0, exchange -> {
            invocations.incrementAndGet();
            return false;
        }, true);
        final Path file = writeSource("predicate-rejects.txt", "content");

        assertNull(manager.getResource(resource("predicate-rejects.txt", file, 7L),
                exchangeWithAcceptEncoding(ENCODING)));
        assertEquals(1, invocations.get());
    }

    @Test
    void succeedsWhenEncodingPredicateAcceptsExchange() throws IOException {
        final AtomicInteger invocations = new AtomicInteger();
        manager = newManager(0, 0, exchange -> {
            invocations.incrementAndGet();
            return true;
        }, true);
        final Path file = writeSource("predicate-accepts.txt", "content");

        final ContentEncodedResource result = manager.getResource(
                resource("predicate-accepts.txt", file, 7L), exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(1, invocations.get());
    }

    @Test
    void returnsNullWhenNoAcceptEncodingHeader() throws IOException {
        final Path file = writeSource("no-header.txt", "content");

        assertNull(manager.getResource(resource("no-header.txt", file, 7L),
                exchangeWithAcceptEncoding(null)));
    }

    @Test
    void returnsNullWhenNoEncodingsAreAllowed() throws IOException {
        final Path file = writeSource("no-encodings.txt", "content");

        // "*;q=0" causes the repository to report an empty (explicitly disallowed) encoding list.
        assertNull(manager.getResource(resource("no-encodings.txt", file, 7L),
                exchangeWithAcceptEncoding("*;q=0")));
    }

    @Test
    void returnsNullWhenChosenEncodingIsIdentity() throws IOException {
        final Path file = writeSource("identity.txt", "content");

        assertNull(manager.getResource(resource("identity.txt", file, 7L),
                exchangeWithAcceptEncoding("identity")));
    }

    @Test
    void returnsNullWhenChosenEncodingPredicateIsFalse() throws IOException {
        manager = newManager(0, 0, null, false);
        final Path file = writeSource("encoding-disabled.txt", "content");

        // The encoding mapping exists but its predicate never resolves, so getEncoding() is null.
        assertNull(manager.getResource(resource("encoding-disabled.txt", file, 7L),
                exchangeWithAcceptEncoding(ENCODING)));
    }

    // ---------------------------------------------------------------------
    // Pre-compressed resource and locking
    // ---------------------------------------------------------------------

    @Test
    void returnsExistingPreCompressedResourceWithoutOpeningSource() throws IOException {
        final Path source = tempDir.resolve("precompressed.txt");
        // Deliberately do not create the source file: the method must return before opening it.
        final Path encodedFile = tempDir.resolve(newPath("precompressed.txt"));
        Files.write(encodedFile, "already compressed".getBytes(StandardCharsets.UTF_8));

        final ContentEncodedResource result = manager.getResource(
                resource("precompressed.txt", source, 5L), exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(ENCODING, result.getContentEncoding());
        assertNotNull(result.getResource());
        assertEquals(encodedFile, result.getResource().getFilePath());
        assertArrayEquals("already compressed".getBytes(StandardCharsets.UTF_8),
                Files.readAllBytes(result.getResource().getFilePath()));
    }

    @Test
    void returnsNullWhenAnotherThreadHoldsTheLock() throws Exception {
        final Path source = tempDir.resolve("locked.txt");
        final ConcurrentMap<Object, Object> locks = lockMap(manager);
        locks.put(lockKey("locked.txt", ENCODING), manager);

        assertNull(manager.getResource(resource("locked.txt", source, 5L),
                exchangeWithAcceptEncoding(ENCODING)));
        assertTrue(locks.containsKey(lockKey("locked.txt", ENCODING)));
        assertFalse(Files.exists(tempDir.resolve(newPath("locked.txt"))));
    }

    @Test
    void releasesLockAndPropagatesIOExceptionWhenSourceCannotBeOpened() throws Exception {
        final Path missingSource = tempDir.resolve("missing-source.txt");

        assertThrows(IOException.class, () -> manager.getResource(
                resource("missing-source.txt", missingSource, 5L), exchangeWithAcceptEncoding(ENCODING)));

        assertTrue(lockMap(manager).isEmpty(),
                "The per-resource lock must be removed even when compression fails");
    }

    // ---------------------------------------------------------------------
    // Successful compression and observable side effects
    // ---------------------------------------------------------------------

    @Test
    void writesEncodedFileAndReturnsEncodedResource() throws IOException {
        final String content = "hello pre-compressed world";
        final Path source = writeSource("written.txt", content);

        final ContentEncodedResource result = manager.getResource(
                resource("written.txt", source, content.length()), exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(ENCODING, result.getContentEncoding());
        assertNotNull(result.getResource());

        final Path encodedFile = tempDir.resolve(newPath("written.txt"));
        assertTrue(Files.exists(encodedFile));
        assertEquals(encodedFile, result.getResource().getFilePath());
        assertArrayEquals(content.getBytes(StandardCharsets.UTF_8), Files.readAllBytes(encodedFile));
        // The source resource is left untouched.
        assertArrayEquals(content.getBytes(StandardCharsets.UTF_8), Files.readAllBytes(source));
    }

    @Test
    void returnsEncodedResourceEvenWhenFewerBytesThanDeclaredWereTransferred() throws IOException {
        final String content = "short";
        final Path source = writeSource("short-read.txt", content);

        // The actual file is shorter than the declared content length. The method logs the
        // mismatch but still returns the (partially written) encoded resource.
        final ContentEncodedResource result = manager.getResource(
                resource("short-read.txt", source, content.length() + 100L),
                exchangeWithAcceptEncoding(ENCODING));

        assertNotNull(result);
        assertEquals(ENCODING, result.getContentEncoding());
        final Path encodedFile = tempDir.resolve(newPath("short-read.txt"));
        assertTrue(Files.exists(encodedFile));
        assertArrayEquals(content.getBytes(StandardCharsets.UTF_8), Files.readAllBytes(encodedFile));
    }

    // ---------------------------------------------------------------------
    // Test doubles
    // ---------------------------------------------------------------------

    /**
     * A {@link CachingResourceManager} backed directly by a directory on disk. It lets the tests
     * observe whether the encoded file was produced without relying on the production caching
     * implementation.
     */
    private static final class TestCachingResourceManager extends CachingResourceManager {

        private final Path root;

        private TestCachingResourceManager(Path root) {
            super(0, 0L, null, ResourceManager.EMPTY_RESOURCE_MANAGER,
                    CachingResourceManager.MAX_AGE_NO_CACHING);
            this.root = root;
        }

        @Override
        public Resource getResource(String path) throws IOException {
            if (path == null) {
                return null;
            }
            final String relative = path.startsWith("/") ? path.substring(1) : path;
            final Path file = root.resolve(relative);
            if (!Files.isRegularFile(file)) {
                return null;
            }
            return new TestResource(path, file, Files.size(file));
        }

        @Override
        public void invalidate(String path) {
            // Nothing is cached, so invalidation is a no-op.
        }
    }

    private static final class TestResource implements Resource {

        private final String path;
        private final Path file;
        private final Long contentLength;

        private TestResource(String path, Path file, Long contentLength) {
            this.path = path;
            this.file = file;
            this.contentLength = contentLength;
        }

        @Override
        public String getPath() {
            return path;
        }

        @Override
        public Date getLastModified() {
            return null;
        }

        @Override
        public String getLastModifiedString() {
            return null;
        }

        @Override
        public ETag getETag() {
            return null;
        }

        @Override
        public String getName() {
            return path;
        }

        @Override
        public boolean isDirectory() {
            return false;
        }

        @Override
        public List<Resource> list() {
            return null;
        }

        @Override
        public String getContentType(MimeMappings mimeMappings) {
            return null;
        }

        @Override
        public void serve(Sender sender, HttpServerExchange exchange, IoCallback completionCallback) {
            throw new UnsupportedOperationException();
        }

        @Override
        public Long getContentLength() {
            return contentLength;
        }

        @Override
        public String getCacheKey() {
            return path;
        }

        @Override
        public File getFile() {
            return file == null ? null : file.toFile();
        }

        @Override
        public Path getFilePath() {
            return file;
        }

        @Override
        public File getResourceManagerRoot() {
            return null;
        }

        @Override
        public Path getResourceManagerRootPath() {
            return null;
        }

        @Override
        public URL getUrl() {
            return null;
        }
    }
}
