        sink.enqueueFlush(true);

        invokeWriteListener();

        assertEquals(0, sink.writeCalls);
        assertEquals(1, sink.flushCalls);
        assertEquals(1, sink.suspendWritesCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertNull(getField(connection, "pooled"));
    }

    @Test
    void failedFlushWithNoPendingDataDoesNotSuspendWrites() throws Exception {
        sink.enqueueFlush(false);

        invokeWriteListener();

        assertEquals(0, sink.writeCalls);
        assertEquals(1, sink.flushCalls);
        assertEquals(0, sink.suspendWritesCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertNull(getField(connection, "pooled"));
    }

    @Test
    void deferredFlushFailureKeepsMessageQueuedAndDoesNotCompleteCallback() throws Exception {
        RecordingCallback callback = new RecordingCallback();
        Object data = createData("payload", "event-name", "event-id", callback);
        flushQueue().add(data);
        sink.enqueueFlush(false);

        invokeWriteListener();

        assertEquals(1, sink.flushCalls);
        assertEquals(0, sink.writeCalls);
        assertEquals(0, callback.doneCount);
        assertEquals(1, flushQueue().size());
        assertSame(data, flushQueue().peek());
    }

    @Test
    void successfulDeferredFlushCompletesOnlyEligibleCallbacksAndClearsQueue() throws Exception {
        RecordingCallback completeCallback = new RecordingCallback();
        RecordingCallback leftoverCallback = new RecordingCallback();
        Object complete = createData("complete", "evt", "1", completeCallback);
        Object leftover = createData("leftover", "evt", "2", leftoverCallback);
        setDataField(leftover, "leftOverData", new byte[]{1, 2, 3});
        flushQueue().add(complete);
        flushQueue().add(leftover);
        flushQueue().add(createData("no-callback", null, null, null));
        TestPooledByteBuffer pooled = new TestPooledByteBuffer(ByteBuffer.wrap("x".getBytes(StandardCharsets.UTF_8)));
        setField(connection, "pooled", pooled);

        invokeWriteListener();

        assertEquals(1, completeCallback.doneCount);
        assertSame(connection, completeCallback.doneConnection);
        assertEquals("complete", completeCallback.doneData);
        assertEquals("evt", completeCallback.doneEvent);
        assertEquals("1", completeCallback.doneId);
        assertEquals(1, completeCallback.flushCallsAtDone);
