        assertEquals("abc", sink.writtenAsString());
        assertTrue(pooled.closed);
    }

    @Test
    void queuedEventIsEncodedByFillBufferAndCallbackRunsAfterSecondWriteIsFlushed() throws Exception {
        TestPooledByteBuffer pooled = new TestPooledByteBuffer(ByteBuffer.wrap("old".getBytes(StandardCharsets.UTF_8)));
        setField(connection, "pooled", pooled);
        RecordingCallback callback = new RecordingCallback();
        Object data = createData("hello", "greet", "7", callback);
        queue().add(data);

        invokeWriteListener();

        assertEquals("oldid:7\nevent:greet\ndata:hello\n\n", sink.writtenAsString());
        assertEquals(1, callback.doneCount);
        assertEquals("hello", callback.doneData);
