        assertEquals(1, sink.resumeWritesCalls);
        assertEquals(1, sink.suspendWritesCalls);
        assertTrue(pooled.closed);
        assertNull(getField(connection, "pooled"));
    }

    @Test
    void ioExceptionClosesConnectionClosesSinkAndFailsQueuedCallbacks() throws Exception {
        TestPooledByteBuffer pooled = new TestPooledByteBuffer(ByteBuffer.wrap("x".getBytes(StandardCharsets.UTF_8)));
        setField(connection, "pooled", pooled);
        RecordingCallback callback = new RecordingCallback();
        queue().add(createData("queued", "event", "id", callback));
        IOException failure = new IOException("write failed");
        sink.failWriteWith(failure);

        invokeWriteListener();

        assertFalse(connection.isOpen());
        assertEquals(1, callback.failureCount);
        assertSame(failure, callback.failure);
        assertEquals("queued", callback.failedData);
        assertEquals("event", callback.failedEvent);
        assertEquals("id", callback.failedId);
