    private void invokeWriteListener() throws Exception {
        Method method = writeListener.getClass().getDeclaredMethod("handleEvent", StreamSinkChannel.class);
        method.setAccessible(true);
        try {
            method.invoke(writeListener, sink.channel());
        } catch (InvocationTargetException e) {
            Throwable cause = e.getCause();
            if (cause instanceof Exception) {
                throw (Exception) cause;
            }
            if (cause instanceof Error) {
                throw (Error) cause;
            }
            throw e;
        }
    }

    @SuppressWarnings("unchecked")
    private static <T> T getField(Object target, String fieldName) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return (T) field.get(target);
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static void setDataField(Object data, String fieldName, Object value) throws Exception {
        Field field = data.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(data, value);
    }

    private static Object createData(String data, String event, String id,
                                     ServerSentEventConnection.EventCallback callback) throws Exception {
        Class<?> dataClass = Class.forName("io.undertow.server.handlers.sse.ServerSentEventConnection$SSEData");
        Constructor<?> constructor = dataClass.getDeclaredConstructor(
                String.class, String.class, String.class, ServerSentEventConnection.EventCallback.class);
        constructor.setAccessible(true);
        return constructor.newInstance(event, data, id, callback);
    }

    @SuppressWarnings("unchecked")
    private Queue<Object> queue() throws Exception {
        return getField(connection, "queue");
    }

    @SuppressWarnings("unchecked")
    private Queue<Object> bufferedQueue() throws Exception {
        return getField(connection, "buffered");
    }

    @SuppressWarnings("unchecked")
    private Deque<Object> flushQueue() throws Exception {
        return getField(connection, "flushingMessages");
    }

    private class RecordingCallback implements ServerSentEventConnection.EventCallback {
        int doneCount;
        int failureCount;
        int flushCallsAtDone = -1;
        ServerSentEventConnection doneConnection;
        String doneData;
        String doneEvent;
        String doneId;
        IOException failure;
        String failedData;
        String failedEvent;
        String failedId;

        @Override
        public void done(ServerSentEventConnection connection, String data, String event, String id) {
            doneCount++;
            flushCallsAtDone = sink.flushCalls;
            doneConnection = connection;
            doneData = data;
            doneEvent = event;
            doneId = id;
        }

        @Override
        public void failed(ServerSentEventConnection connection, String data, String event, String id, IOException e) {
            failureCount++;
            failure = e;
            failedData = data;
            failedEvent = event;
            failedId = id;
        }
    }

    private static final class TestPooledByteBuffer implements PooledByteBuffer {
        private final ByteBuffer buffer;
        private boolean open = true;
        private boolean closed;

        private TestPooledByteBuffer(ByteBuffer buffer) {
            this.buffer = buffer;
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            open = false;
            closed = true;
        }

        @Override
        public boolean isOpen() {
            return open;
        }
    }

    private static final class FakeSink implements InvocationHandler {
        private final ChannelListener.SimpleSetter<StreamSinkChannel> writeSetter = new ChannelListener.SimpleSetter<>();
        private final ChannelListener.SimpleSetter<StreamSinkChannel> closeSetter = new ChannelListener.SimpleSetter<>();
        private final Deque<Integer> writeCounts = new ArrayDeque<>();
        private final Deque<Boolean> flushResults = new ArrayDeque<>();
        private final ByteArrayOutputStream written = new ByteArrayOutputStream();
        private final StreamSinkChannel channel;
        private IOException writeFailure;
        private int writeCalls;
        private int flushCalls;
        private int resumeWritesCalls;
        private int suspendWritesCalls;
        private int shutdownWritesCalls;
        private int closeCalls;
        private boolean open = true;

        private FakeSink() {
            channel = (StreamSinkChannel) Proxy.newProxyInstance(
                    StreamSinkChannel.class.getClassLoader(),
                    new Class<?>[]{StreamSinkChannel.class},
                    this);
        }

        private StreamSinkChannel channel() {
            return channel;
        }

        private void enqueueWrite(int count) {
            writeCounts.add(count);
        }

        private void enqueueFlush(boolean result) {
            flushResults.add(result);
        }

        private void failWriteWith(IOException failure) {
            writeFailure = failure;
        }

        private String writtenAsString() {
            return new String(written.toByteArray(), StandardCharsets.UTF_8);
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            String name = method.getName();
            switch (name) {
                case "write":
                    if (args != null && args.length == 1 && args[0] instanceof ByteBuffer) {
                        writeCalls++;
                        if (writeFailure != null) {
                            throw writeFailure;
                        }
                        ByteBuffer buffer = (ByteBuffer) args[0];
                        int requested = writeCounts.isEmpty() ? buffer.remaining() : writeCounts.removeFirst();
                        int count = Math.min(Math.max(requested, 0), buffer.remaining());
                        if (count > 0) {
                            byte[] bytes = new byte[count];
                            buffer.get(bytes);
                            written.write(bytes, 0, bytes.length);
                        }
                        return count;
                    }
                    return 0;
                case "flush":
                    flushCalls++;
                    return flushResults.isEmpty() ? Boolean.TRUE : flushResults.removeFirst();
                case "getWriteSetter":
                    return writeSetter;
                case "getCloseSetter":
                    return closeSetter;
                case "resumeWrites":
                    resumeWritesCalls++;
                    return null;
                case "suspendWrites":
                    suspendWritesCalls++;
                    return null;
                case "shutdownWrites":
                    shutdownWritesCalls++;
                    return null;
                case "close":
                    closeCalls++;
                    open = false;
                    return null;
                case "isOpen":
                    return open;
                case "isWriteResumed":
                    return false;
                case "getIoThread":
                case "getWriteThread":
                case "getWorker":
                    return null;
                case "supportsOption":
                    return false;
                case "getOption":
                    return null;
                case "setOption":
                    return args == null || args.length < 2 ? null : args[1];
                case "equals":
                    return proxy == args[0];
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "toString":
                    return "FakeStreamSinkChannel";
                default:
                    return defaultValue(method.getReturnType());
            }
        }

        private static Object defaultValue(Class<?> type) {
            if (!type.isPrimitive()) {
                return null;
            }
            if (type == boolean.class) {
                return false;
            }
            if (type == byte.class) {
                return (byte) 0;
            }
            if (type == short.class) {
                return (short) 0;
            }
            if (type == int.class) {
                return 0;
            }
            if (type == long.class) {
                return 0L;
            }
            if (type == float.class) {
                return 0F;
            }
            if (type == double.class) {
                return 0D;
            }
            if (type == char.class) {
                return (char) 0;
            }
            return null;
        }
    }
