        public SSLEngine setProtocols(SSLEngine engine, String[] protocols) {
            return engine;
        }

        @Override
        public String getSelectedProtocol(SSLEngine engine) {
            getSelectedProtocolInvocations++;
            seenEngine = engine;
            return selectedProtocol;
        }

        @Override
        public int getPriority() {
            return 0;
        }
