        allocateCount++;
        if (throwOnAllocate) throw new IllegalStateException("pool closed");
        TrackingPooledByteBuffer b = new TrackingPooledByteBuffer(ByteBuffer.allocate(size));
        allocated.add(b);
        return b;
    }
    public ByteBufferPool getArrayBackedPool() { return this; }
    public void close() {}
    public int getBufferSize() { return size; }
