private static final class TestSinkConduit implements StreamSinkConduit {
    private final XnioIoThread ioThread;
    private final ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    private WriteReadyHandler writeReadyHandler;
    private boolean writeShutdown;
    private int suspendCount, resumeCount, flushCount, writeCount;

    String text() { return new String(buffer.toByteArray(), StandardCharsets.US_ASCII); }

    @Override public void terminateWrites() { writeShutdown = true; }
    @Override public boolean isWriteShutdown() { return writeShutdown; }
    @Override public void resumeWrites() { resumeCount++; }
    @Override public void suspendWrites() { suspendCount++; }
    @Override public void wakeupWrites() { resumeCount++; }
    @Override public boolean isWriteResumed() { return false; }
    @Override public void awaitWritable() {}
    @Override public void awaitWritable(long time, TimeUnit unit) {}
    @Override public XnioIoThread getWriteThread() { return ioThread; }
    @Override public void setWriteReadyHandler(WriteReadyHandler handler) { this.writeReadyHandler = handler; }
    @Override public void truncateWrites() { }
    @Override public boolean flush() { flushCount++; return true; }
    @Override public XnioWorker getWorker() { return ioThread.getWorker(); }
    @Override public long transferFrom(FileChannel src, long position, long count) { return 0; }
    @Override public long transferFrom(StreamSourceChannel source, long count, ByteBuffer throughBuffer) { return 0; }
    @Override public int write(ByteBuffer src) { writeCount++; int n = src.remaining(); byte[] b = new byte[n]; src.get(b); buffer.write(b, 0, n); return n; }
    @Override public long write(ByteBuffer[] srcs, int offs, int len) { long total = 0; for (int i = offs; i < offs+len; i++) total += write(srcs[i]); return total; }
    @Override public int writeFinal(ByteBuffer src) { int r = write(src); terminateWrites(); return r; }
    @Override public long writeFinal(ByteBuffer[] srcs, int offs, int len) { long r = write(srcs, offs, len); terminateWrites(); return r; }
}
