/**
 * Tests for {@link HttpReadListener#handleEventWithNoRunningRequest(org.xnio.conduits.ConduitStreamSourceChannel)}.
 * <p>
 * The listener under test is driven with a plain {@link StreamConnection} whose conduits are scriptable test
 * doubles, so that every branch of the method (connection shutdown, allocation failures, io failures, partial
 * reads, parse failures, pipelined data, request size limits and successful request dispatch) can be observed
 * without any real socket.
 */
class HttpReadListenerHandleEventWithNoRunningRequestTests {

    private static final Executor NO_OP_EXECUTOR = new Executor() {
        @Override
        public void execute(final Runnable command) {
            // intentionally never runs the dispatched task, the exchange is kept "in progress"
        }
    };

    private static XnioWorker worker;
    private static XnioIoThread ioThread;

    private final List<Harness> harnesses = new ArrayList<>();

    @BeforeAll
    static void startWorker() throws IOException {
        worker = Xnio.getInstance().createWorker(OptionMap.create(Options.WORKER_IO_THREADS, 1));
        ioThread = worker.getIoThread();
    }

    @AfterAll
    static void stopWorker() throws Exception {
        if (worker != null) {
            worker.shutdownNow();
            worker.awaitTermination(30, TimeUnit.SECONDS);
        }
    }

    @AfterEach
    void releaseHarnesses() {
        for (Harness harness : harnesses) {
            try {
                harness.connection.setExtraBytes(null);
                harness.connection.close();
            } catch (Throwable ignored) {
                // best effort cleanup, the assertions have already been made
            }
        }
        harnesses.clear();
    }

    // ------------------------------------------------------------------
    // connection shutdown handling
    // ------------------------------------------------------------------

    @Test
    void readShutdownWithoutExtraBytesClosesConnectionAndSuspendsReads() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        source.setReadShutdown(true);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertFalse(harness.streamConnection.isOpen(), "the connection must be closed when the source is shut down");
        assertEquals(1, source.suspendCount, "reads must be suspended");
        assertEquals(0, source.readCount, "no read may be attempted on a closing connection");
        assertEquals(0, pool.allocateCount, "no buffer may be allocated on a closing connection");
        assertTrue(handled.isEmpty(), "no exchange may be created on a closing connection");
        assertNull(harness.connection.getExtraBytes());
    }

    @Test
    void writeShutdownClosesConnectionAndSuspendsReads() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        sink.setWriteShutdown(true);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertFalse(source.isReadShutdown(), "the read side is still open");
        assertFalse(harness.streamConnection.isOpen(), "the connection must be closed when the sink is shut down");
        assertEquals(1, source.suspendCount, "reads must be suspended");
        assertEquals(0, source.readCount, "no read may be attempted on a closing connection");
        assertEquals(0, pool.allocateCount, "no buffer may be allocated on a closing connection");
        assertTrue(handled.isEmpty());
    }

    @Test
    void writeShutdownClosesPipelinedExtraBytes() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        TrackingPooledByteBuffer extra = new TrackingPooledByteBuffer(bytes("GET / HTTP/1.1\r\nHost: localhost\r\n\r\n"));
        harness.connection.setExtraBytes(extra);
        sink.setWriteShutdown(true);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertFalse(harness.streamConnection.isOpen());
        assertTrue(extra.isClosed(), "buffered request data must be released when the connection is closed");
        assertNull(harness.connection.getExtraBytes());
        assertTrue(handled.isEmpty());
    }

    @Test
    void readShutdownIsIgnoredWhenPipelinedDataIsAvailable() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        TrackingPooledByteBuffer extra = new TrackingPooledByteBuffer(bytes("GET /pipelined HTTP/1.0\r\n\r\n"));
        harness.connection.setExtraBytes(extra);
        source.setReadShutdown(true);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertEquals(1, handled.size(), "buffered request bytes must still be parsed when the read side is shut down");
        HttpServerExchange exchange = handled.get(0);
        assertEquals("GET", exchange.getRequestMethod().toString());
        assertEquals("/pipelined", exchange.getRequestPath());
        assertEquals("HTTP/1.0", exchange.getProtocol().toString());
        assertTrue(harness.streamConnection.isOpen(), "the connection must not be closed, the request was parsed");
        assertEquals(0, source.readCount, "the channel must not be read, the data was already buffered");
        assertEquals(0, pool.allocateCount, "the buffered data must be reused, no allocation is needed");
    }

    @Test
    void bufferPoolFailureClosesConnectionAndSuspendsReads() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, true);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertEquals(1, pool.allocateCount, "the listener must have tried to allocate a buffer");
        assertEquals(0, source.readCount);
        assertEquals(1, source.suspendCount, "reads must be suspended when the pool is shut down");
        assertFalse(harness.streamConnection.isOpen(), "the connection must be closed when the pool is shut down");
        assertTrue(handled.isEmpty());
    }

