    @Test
    void readReturningZeroRegistersReadListenerAndResumesReads() {
        TestSourceConduit source = new TestSourceConduit(ioThread);
        TestSinkConduit sink = new TestSinkConduit(ioThread);
        TrackingByteBufferPool pool = new TrackingByteBufferPool(2048, false);
        List<HttpServerExchange> handled = new ArrayList<>();
        Harness harness = harness(source, sink, OptionMap.EMPTY, pool, handled);

        source.addReadResult(0);

        harness.listener.handleEventWithNoRunningRequest(harness.streamConnection.getSourceChannel());

        assertEquals(1, source.readCount);
        assertEquals(1, source.resumeCount, "reads must be resumed so the listener is called again");
        assertNotNull(source.readReadyHandler, "a read ready handler must be registered");
        assertSame(harness.listener, harness.streamConnection.getSourceChannel().getReadListener(),
                "the read listener must be the listener itself");
        assertTrue(harness.streamConnection.isOpen(), "an empty read must not close the connection");
        assertTrue(handled.isEmpty());
        assertEquals(1, pool.allocateCount);
        assertTrue(pool.lastAllocated().isClosed(), "the scratch buffer must be released when nothing was read");
    }

    @Test
