    private void initiate(
            ChannelListener<? super StreamSourceChannel> readListener,
            ChannelListener<? super StreamSinkChannel> writeListener,
            ChannelExceptionHandler<? super StreamSourceChannel> readHandler,
            ChannelExceptionHandler<? super StreamSinkChannel> writeHandler,
            ByteBufferPool bufferPool) {
        Transfer.initiateTransfer(source.channel(), sink.channel(), readListener, writeListener,
                readHandler, writeHandler, bufferPool);
    }

    private static Object defaultValue(Class<?> returnType) {
        if (returnType == void.class) {
            return null;
        }
        if (returnType == boolean.class) {
            return false;
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0.0f;
        }
        if (returnType == double.class) {
            return 0.0d;
        }
        if (returnType == char.class) {
            return '\0';
        }
        return null;
    }

    private static final class RecordingSetter<T extends Channel>
            implements ChannelListener.Setter<T> {

        private ChannelListener<? super T> listener;
        private int setCalls;

        @Override
        public void set(ChannelListener<? super T> listener) {
            this.listener = listener;
            setCalls++;
        }
    }

    private static final class SourceStub {

        private final Deque<ReadEvent> reads = new ArrayDeque<>();
        private final RecordingSetter<StreamSourceChannel> readSetter = new RecordingSetter<>();
        private final RecordingSetter<StreamSourceChannel> closeSetter = new RecordingSetter<>();
        private final StreamSourceChannel channel;
        private int readCalls;
        private int resumeReadsCalls;
        private int suspendReadsCalls;
        private int wakeupReadsCalls;
        private boolean readResumed;
        private boolean open = true;

        private SourceStub() {
            channel = (StreamSourceChannel) Proxy.newProxyInstance(
                    SourceStub.class.getClassLoader(),
                    new Class<?>[]{StreamSourceChannel.class},
                    this::invoke);
        }

        private StreamSourceChannel channel() {
            return channel;
        }

        private SourceStub data(String value) {
            return data(value.getBytes(StandardCharsets.UTF_8));
        }

        private SourceStub data(byte[] value) {
            reads.add(ReadEvent.data(value));
            return this;
        }

        private SourceStub zero() {
            reads.add(ReadEvent.count(0));
            return this;
        }

        private SourceStub eof() {
            reads.add(ReadEvent.count(-1));
            return this;
        }

        private SourceStub failWith(IOException failure) {
            reads.add(ReadEvent.failure(failure));
            return this;
        }

        private SourceStub runtimeFailure(RuntimeException failure) {
            reads.add(ReadEvent.failure(failure));
            return this;
        }

        private Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            switch (method.getName()) {
                case "read":
                    readCalls++;
                    if (args == null || args.length != 1 || !(args[0] instanceof ByteBuffer)) {
                        return 0L;
                    }
                    ReadEvent event = reads.poll();
                    if (event == null) {
                        throw new AssertionError("No source read result configured");
                    }
                    if (event.failure != null) {
                        throw event.failure;
                    }
                    if (event.data != null) {
                        ((ByteBuffer) args[0]).put(event.data);
                    }
                    return event.count;
                case "getReadSetter":
                    return readSetter;
                case "getCloseSetter":
                    return closeSetter;
                case "resumeReads":
                    resumeReadsCalls++;
                    readResumed = true;
                    return null;
                case "suspendReads":
                    suspendReadsCalls++;
                    readResumed = false;
                    return null;
                case "wakeupReads":
                    wakeupReadsCalls++;
                    return null;
                case "isReadResumed":
                    return readResumed;
                case "close":
                    open = false;
                    readResumed = false;
                    return null;
                case "isOpen":
                    return open;
                case "toString":
                    return "test-source";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }
    }

    private static final class SinkStub {

        private final Deque<WriteEvent> writes = new ArrayDeque<>();
        private final RecordingSetter<StreamSinkChannel> writeSetter = new RecordingSetter<>();
        private final RecordingSetter<StreamSinkChannel> closeSetter = new RecordingSetter<>();
        private final StreamSinkChannel channel;
        private int writeCalls;
        private int resumeWritesCalls;
        private int suspendWritesCalls;
        private int wakeupWritesCalls;
        private int bytesWritten;
        private boolean writeResumed;
        private boolean open = true;

        private SinkStub() {
            channel = (StreamSinkChannel) Proxy.newProxyInstance(
                    SinkStub.class.getClassLoader(),
                    new Class<?>[]{StreamSinkChannel.class},
                    this::invoke);
        }

        private StreamSinkChannel channel() {
            return channel;
        }

        private SinkStub write(int count) {
            writes.add(WriteEvent.count(count));
            return this;
        }

        private SinkStub consumeAll() {
            writes.add(WriteEvent.count(Integer.MAX_VALUE));
            return this;
        }

        private SinkStub failWith(IOException failure) {
            writes.add(WriteEvent.failure(failure));
            return this;
        }

        private SinkStub runtimeFailure(RuntimeException failure) {
            writes.add(WriteEvent.failure(failure));
            return this;
        }

        private Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            switch (method.getName()) {
                case "write":
                    writeCalls++;
                    if (args == null || args.length != 1 || !(args[0] instanceof ByteBuffer)) {
                        return 0;
                    }
                    WriteEvent event = writes.poll();
                    if (event == null) {
                        throw new AssertionError("No sink write result configured");
                    }
                    if (event.failure != null) {
                        throw event.failure;
                    }
                    ByteBuffer buffer = (ByteBuffer) args[0];
                    int count = Math.min(event.count, buffer.remaining());
                    buffer.position(buffer.position() + count);
                    bytesWritten += count;
                    return count;
                case "getWriteSetter":
                    return writeSetter;
                case "getCloseSetter":
                    return closeSetter;
                case "resumeWrites":
                    resumeWritesCalls++;
                    writeResumed = true;
                    return null;
                case "suspendWrites":
                    suspendWritesCalls++;
                    writeResumed = false;
                    return null;
                case "wakeupWrites":
                    wakeupWritesCalls++;
                    return null;
                case "isWriteResumed":
                    return writeResumed;
                case "close":
                    open = false;
                    writeResumed = false;
                    return null;
                case "isOpen":
                    return open;
                case "toString":
                    return "test-sink";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }
