    private static final class ReadEvent {

        private final long count;
        private final byte[] data;
        private final Throwable failure;

        private ReadEvent(long count, byte[] data, Throwable failure) {
            this.count = count;
            this.data = data;
            this.failure = failure;
        }

        private static ReadEvent data(byte[] data) {
            return new ReadEvent(data.length, data, null);
