                    new Class<?>[]{ByteBufferPool.class},
                    this::invoke);
        }

        private ByteBufferPool proxy() {
            return proxy;
        }

        private TestPooledByteBuffer singleBuffer() {
            assertEquals(1, allocated.size());
            return allocated.get(0);
        }

        private Object invoke(Object proxy, Method method, Object[] args) {
            switch (method.getName()) {
                case "allocate":
                    TestPooledByteBuffer buffer = new TestPooledByteBuffer(capacity);
                    allocated.add(buffer);
                    return buffer.proxy();
                case "getBufferSize":
                    return capacity;
                case "isDirect":
                    return false;
                case "close":
                    return null;
                case "toString":
                    return "test-byte-buffer-pool";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }
    }

    private static final class TestPooledByteBuffer {

        private final ByteBuffer buffer;
        private final PooledByteBuffer proxy;
        private boolean closed;
        private boolean open = true;

        private TestPooledByteBuffer(int capacity) {
            this.buffer = ByteBuffer.allocate(capacity);
