    @Test
    void rejectsNullPoolBeforeTouchingChannels() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> initiate(sourceListener, sinkListener, null, null, null));

        assertTrue(exception.getMessage().contains("pool"),
                () -> "Exception message should identify the null argument: "
                        + exception.getMessage());
        assertEquals(0, source.readCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
    }

    @Test
    void invokesReadExceptionHandlerAndReleasesBufferOnReadFailure() {
        IOException failure = new IOException("read failed");
        source.failWith(failure);
        AtomicReference<StreamSourceChannel> seenChannel = new AtomicReference<>();
        AtomicReference<IOException> seenFailure = new AtomicReference<>();

        initiate(sourceListener, sinkListener,
                (channel, exception) -> {
                    seenChannel.set(channel);
                    seenFailure.set(exception);
                },
                (channel, exception) -> fail(
                        "write exception handler must not be called"),
                pool.proxy());

        assertSame(failure, seenFailure.get());
        assertSame(source.channel(), seenChannel.get());
        assertEquals(1, source.readCalls);
        assertEquals(0, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void invokesWriteExceptionHandlerAndReleasesBufferOnWriteFailure() {
        source.data(ABC);
        IOException failure = new IOException("write failed");
        sink.failWith(failure);
        AtomicReference<StreamSinkChannel> seenChannel = new AtomicReference<>();
        AtomicReference<IOException> seenFailure = new AtomicReference<>();

        initiate(sourceListener, sinkListener,
                (channel, exception) -> fail(
                        "read exception handler must not be called"),
                (channel, exception) -> {
                    seenChannel.set(channel);
                    seenFailure.set(exception);
                },
                pool.proxy());

        assertSame(failure, seenFailure.get());
        assertSame(sink.channel(), seenChannel.get());
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void immediateEofRestoresCallerListenersAndWakesChannels() {
        source.eof();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void immediateEofWithNullListenersSuspendsBothChannels() {
        source.eof();

        initiate(null, null, null, null, pool.proxy());

        assertNull(source.readSetter.listener);
        assertNull(sink.writeSetter.listener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.suspendReadsCalls);
        assertEquals(1, sink.suspendWritesCalls);
        assertEquals(0, source.wakeupReadsCalls);
        assertEquals(0, sink.wakeupWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void readOfZeroInstallsCombinedListenerAndResumesOnlyReads() {
        source.zero();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertNotSame(sinkListener, transferListener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertEquals(0, source.wakeupReadsCalls);
        assertEquals(0, sink.wakeupWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void fullRetainedBufferDoesNotResumeReads() {
        TestPool smallPool = new TestPool(4);
        source.data(new byte[]{1, 2, 3, 4});
        sink.write(0);

        initiate(sourceListener, sinkListener, null, null, smallPool.proxy());

        TestPooledByteBuffer buffer = smallPool.singleBuffer();
        assertFalse(buffer.closed);
        assertEquals(0, buffer.buffer.position());
        assertEquals(4, buffer.buffer.remaining());
        assertEquals(4, buffer.buffer.capacity());
        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(1, sink.resumeWritesCalls);
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, sink.bytesWritten);
    }

    @Test
    void fullyWrittenDataFollowedByReadZeroInstallsListener() {
        source.data(ABC);
        source.zero();
        sink.consumeAll();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertEquals(2, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void fullyWrittenDataFollowedByEofCompletesSynchronously() {
        source.data(ABC);
        source.eof();
        sink.consumeAll();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(2, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void installedListenerFinishesPartialWriteAndRestoresCallerListeners() {
        source.data(ABC);
        source.eof();
        sink.write(1);
        sink.write(0);

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertFalse(buffer.closed);
        assertEquals(1, buffer.buffer.position());
        assertEquals(2, buffer.buffer.remaining());
        ChannelListener<? super StreamSinkChannel> transferListener = sink.writeSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, source.readSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertNotSame(sinkListener, transferListener);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(1, sink.resumeWritesCalls);
        assertEquals(1, sink.bytesWritten);

        sink.consumeAll();
        transferListener.handleEvent(sink.channel());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(2, source.readCalls);
        assertEquals(3, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void releasesBufferWhenReadThrowsUncheckedException() {
        IllegalStateException failure = new IllegalStateException("read runtime failure");
        source.runtimeFailure(failure);

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> initiate(sourceListener, sinkListener,
                        (channel, exception) -> fail(
                                "read handler only handles IOException"),
                        (channel, exception) -> fail(
                                "write handler must not be called"),
                        pool.proxy()));

        assertSame(failure, thrown);
        assertEquals(1, source.readCalls);
        assertEquals(0, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void releasesBufferWhenWriteThrowsUncheckedException() {
        source.data(ABC);
        IllegalStateException failure = new IllegalStateException("write runtime failure");
        sink.runtimeFailure(failure);

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> initiate(sourceListener, sinkListener,
                        (channel, exception) -> fail(
                                "read handler must not be called"),
                        (channel, exception) -> fail(
                                "write handler only handles IOException"),
                        pool.proxy()));

        assertSame(failure, thrown);
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    private void initiate(
            ChannelListener<? super StreamSourceChannel> readListener,
            ChannelListener<? super StreamSinkChannel> writeListener,
            ChannelExceptionHandler<? super StreamSourceChannel> readHandler,
            ChannelExceptionHandler<? super StreamSinkChannel> writeHandler,
            ByteBufferPool bufferPool) {
        Transfer.initiateTransfer(source.channel(), sink.channel(), readListener, writeListener,
                readHandler, writeHandler, bufferPool);
    }

    private static Object defaultValue(Class<?> returnType) {
        if (returnType == void.class) {
            return null;
        }
        if (returnType == boolean.class) {
            return false;
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0.0f;
        }
        if (returnType == double.class) {
            return 0.0d;
        }
        if (returnType == char.class) {
            return '\0';
        }
        return null;
    }

    private static final class RecordingSetter<T extends Channel>
            implements ChannelListener.Setter<T> {

        private ChannelListener<? super T> listener;
        private int setCalls;

        @Override
        public void set(ChannelListener<? super T> listener) {
            this.listener = listener;
            setCalls++;
        }
    }

    private static final class SourceStub {

        private final Deque<ReadEvent> reads = new ArrayDeque<>();
        private final RecordingSetter<StreamSourceChannel> readSetter = new RecordingSetter<>();
        private final RecordingSetter<StreamSourceChannel> closeSetter = new RecordingSetter<>();
        private final StreamSourceChannel channel;
