package io.undertow.util;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import io.undertow.connector.ByteBufferPool;
import io.undertow.connector.PooledByteBuffer;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.xnio.ChannelExceptionHandler;
import org.xnio.ChannelListener;
import org.xnio.channels.StreamSinkChannel;
import org.xnio.channels.StreamSourceChannel;

import java.io.IOException;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.nio.ByteBuffer;
import java.nio.channels.Channel;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;

class TransferInitiateTransferTests {

    private static final byte[] ABC = {'a', 'b', 'c'};

    private SourceStub source;
    private SinkStub sink;
    private TestPool pool;
    private ChannelListener<StreamSourceChannel> sourceListener;
    private ChannelListener<StreamSinkChannel> sinkListener;

    @BeforeEach
    void setUp() {
        source = new SourceStub();
        sink = new SinkStub();
        pool = new TestPool(16);
        sourceListener = channel -> { };
        sinkListener = channel -> { };
    }

    @Test
    void rejectsNullPoolBeforeTouchingChannels() {
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class,
                () -> initiate(sourceListener, sinkListener, null, null, null));

        assertTrue(exception.getMessage().contains("pool"),
                () -> "Exception message should identify the null argument: "
                        + exception.getMessage());
        assertEquals(0, source.readCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
    }

    @Test
    void invokesReadExceptionHandlerAndReleasesBufferOnReadFailure() {
        IOException failure = new IOException("read failed");
        source.failWith(failure);
        AtomicReference<StreamSourceChannel> seenChannel = new AtomicReference<>();
        AtomicReference<IOException> seenFailure = new AtomicReference<>();

        initiate(sourceListener, sinkListener,
                (channel, exception) -> {
                    seenChannel.set(channel);
                    seenFailure.set(exception);
                },
                (channel, exception) -> fail(
                        "write exception handler must not be called"),
                pool.proxy());

        assertSame(failure, seenFailure.get());
        assertSame(source.channel(), seenChannel.get());
        assertEquals(1, source.readCalls);
        assertEquals(0, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void invokesWriteExceptionHandlerAndReleasesBufferOnWriteFailure() {
        source.data(ABC);
        IOException failure = new IOException("write failed");
        sink.failWith(failure);
        AtomicReference<StreamSinkChannel> seenChannel = new AtomicReference<>();
        AtomicReference<IOException> seenFailure = new AtomicReference<>();

        initiate(sourceListener, sinkListener,
                (channel, exception) -> fail(
                        "read exception handler must not be called"),
                (channel, exception) -> {
                    seenChannel.set(channel);
                    seenFailure.set(exception);
                },
                pool.proxy());

        assertSame(failure, seenFailure.get());
        assertSame(sink.channel(), seenChannel.get());
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void immediateEofRestoresCallerListenersAndWakesChannels() {
        source.eof();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void immediateEofWithNullListenersSuspendsBothChannels() {
        source.eof();

        initiate(null, null, null, null, pool.proxy());

        assertNull(source.readSetter.listener);
        assertNull(sink.writeSetter.listener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.suspendReadsCalls);
        assertEquals(1, sink.suspendWritesCalls);
        assertEquals(0, source.wakeupReadsCalls);
        assertEquals(0, sink.wakeupWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void readOfZeroInstallsCombinedListenerAndResumesOnlyReads() {
        source.zero();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertNotSame(sinkListener, transferListener);
        assertEquals(1, source.readSetter.setCalls);
        assertEquals(1, sink.writeSetter.setCalls);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertEquals(0, source.wakeupReadsCalls);
        assertEquals(0, sink.wakeupWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void fullRetainedBufferDoesNotResumeReads() {
        TestPool smallPool = new TestPool(4);
        source.data(new byte[]{1, 2, 3, 4});
        sink.write(0);

        initiate(sourceListener, sinkListener, null, null, smallPool.proxy());

        TestPooledByteBuffer buffer = smallPool.singleBuffer();
        assertFalse(buffer.closed);
        assertEquals(0, buffer.buffer.position());
        assertEquals(4, buffer.buffer.remaining());
        assertEquals(4, buffer.buffer.capacity());
        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(1, sink.resumeWritesCalls);
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, sink.bytesWritten);
    }

    @Test
    void fullyWrittenDataFollowedByReadZeroInstallsListener() {
        source.data(ABC);
        source.zero();
        sink.consumeAll();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        ChannelListener<?> transferListener = source.readSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, sink.writeSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertEquals(2, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void fullyWrittenDataFollowedByEofCompletesSynchronously() {
        source.data(ABC);
        source.eof();
        sink.consumeAll();

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(2, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertEquals(0, source.resumeReadsCalls);
        assertEquals(0, sink.resumeWritesCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void installedListenerFinishesPartialWriteAndRestoresCallerListeners() {
        source.data(ABC);
        source.eof();
        sink.write(1);
        sink.write(0);

        initiate(sourceListener, sinkListener, null, null, pool.proxy());

        TestPooledByteBuffer buffer = pool.singleBuffer();
        assertFalse(buffer.closed);
        assertEquals(1, buffer.buffer.position());
        assertEquals(2, buffer.buffer.remaining());
        ChannelListener<? super StreamSinkChannel> transferListener = sink.writeSetter.listener;
        assertNotNull(transferListener);
        assertSame(transferListener, source.readSetter.listener);
        assertNotSame(sourceListener, transferListener);
        assertNotSame(sinkListener, transferListener);
        assertEquals(1, source.resumeReadsCalls);
        assertEquals(1, sink.resumeWritesCalls);
        assertEquals(1, sink.bytesWritten);

        sink.consumeAll();
        transferListener.handleEvent(sink.channel());

        assertSame(sourceListener, source.readSetter.listener);
        assertSame(sinkListener, sink.writeSetter.listener);
        assertEquals(2, source.readCalls);
        assertEquals(3, sink.writeCalls);
        assertEquals(3, sink.bytesWritten);
        assertEquals(1, source.wakeupReadsCalls);
        assertEquals(1, sink.wakeupWritesCalls);
        assertTrue(buffer.closed);
        assertFalse(buffer.open);
    }

    @Test
    void releasesBufferWhenReadThrowsUncheckedException() {
        IllegalStateException failure = new IllegalStateException("read runtime failure");
        source.runtimeFailure(failure);

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> initiate(sourceListener, sinkListener,
                        (channel, exception) -> fail(
                                "read handler only handles IOException"),
                        (channel, exception) -> fail(
                                "write handler must not be called"),
                        pool.proxy()));

        assertSame(failure, thrown);
        assertEquals(1, source.readCalls);
        assertEquals(0, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    @Test
    void releasesBufferWhenWriteThrowsUncheckedException() {
        source.data(ABC);
        IllegalStateException failure = new IllegalStateException("write runtime failure");
        sink.runtimeFailure(failure);

        IllegalStateException thrown = assertThrows(IllegalStateException.class,
                () -> initiate(sourceListener, sinkListener,
                        (channel, exception) -> fail(
                                "read handler must not be called"),
                        (channel, exception) -> fail(
                                "write handler only handles IOException"),
                        pool.proxy()));

        assertSame(failure, thrown);
        assertEquals(1, source.readCalls);
        assertEquals(1, sink.writeCalls);
        assertEquals(0, source.readSetter.setCalls);
        assertEquals(0, sink.writeSetter.setCalls);
        assertTrue(pool.singleBuffer().closed);
    }

    private void initiate(
            ChannelListener<? super StreamSourceChannel> readListener,
            ChannelListener<? super StreamSinkChannel> writeListener,
            ChannelExceptionHandler<? super StreamSourceChannel> readHandler,
            ChannelExceptionHandler<? super StreamSinkChannel> writeHandler,
            ByteBufferPool bufferPool) {
        Transfer.initiateTransfer(source.channel(), sink.channel(), readListener, writeListener,
                readHandler, writeHandler, bufferPool);
    }

    private static Object defaultValue(Class<?> returnType) {
        if (returnType == void.class) {
            return null;
        }
        if (returnType == boolean.class) {
            return false;
        }
        if (returnType == byte.class) {
            return (byte) 0;
        }
        if (returnType == short.class) {
            return (short) 0;
        }
        if (returnType == int.class) {
            return 0;
        }
        if (returnType == long.class) {
            return 0L;
        }
        if (returnType == float.class) {
            return 0.0f;
        }
        if (returnType == double.class) {
            return 0.0d;
        }
        if (returnType == char.class) {
            return '\0';
        }
        return null;
    }

    private static final class RecordingSetter<T extends Channel>
            implements ChannelListener.Setter<T> {

        private ChannelListener<? super T> listener;
        private int setCalls;

        @Override
        public void set(ChannelListener<? super T> listener) {
            this.listener = listener;
            setCalls++;
        }
    }

    private static final class SourceStub {

        private final Deque<ReadEvent> reads = new ArrayDeque<>();
        private final RecordingSetter<StreamSourceChannel> readSetter = new RecordingSetter<>();
        private final RecordingSetter<StreamSourceChannel> closeSetter = new RecordingSetter<>();
        private final StreamSourceChannel channel;
        private int readCalls;
        private int resumeReadsCalls;
        private int suspendReadsCalls;
        private int wakeupReadsCalls;
        private boolean readResumed;
        private boolean open = true;

        private SourceStub() {
            channel = (StreamSourceChannel) Proxy.newProxyInstance(
                    SourceStub.class.getClassLoader(),
                    new Class<?>[]{StreamSourceChannel.class},
                    this::invoke);
        }

        private StreamSourceChannel channel() {
            return channel;
        }

        private SourceStub data(String value) {
            return data(value.getBytes(StandardCharsets.UTF_8));
        }

        private SourceStub data(byte[] value) {
            reads.add(ReadEvent.data(value));
            return this;
        }

        private SourceStub zero() {
            reads.add(ReadEvent.count(0));
            return this;
        }

        private SourceStub eof() {
            reads.add(ReadEvent.count(-1));
            return this;
        }

        private SourceStub failWith(IOException failure) {
            reads.add(ReadEvent.failure(failure));
            return this;
        }

        private SourceStub runtimeFailure(RuntimeException failure) {
            reads.add(ReadEvent.failure(failure));
            return this;
        }

        private Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            switch (method.getName()) {
                case "read":
                    readCalls++;
                    if (args == null || args.length != 1 || !(args[0] instanceof ByteBuffer)) {
                        return 0L;
                    }
                    ReadEvent event = reads.poll();
                    if (event == null) {
                        throw new AssertionError("No source read result configured");
                    }
                    if (event.failure != null) {
                        throw event.failure;
                    }
                    if (event.data != null) {
                        ((ByteBuffer) args[0]).put(event.data);
                    }
                    return event.count;
                case "getReadSetter":
                    return readSetter;
                case "getCloseSetter":
                    return closeSetter;
                case "resumeReads":
                    resumeReadsCalls++;
                    readResumed = true;
                    return null;
                case "suspendReads":
                    suspendReadsCalls++;
                    readResumed = false;
                    return null;
                case "wakeupReads":
                    wakeupReadsCalls++;
                    return null;
                case "isReadResumed":
                    return readResumed;
                case "close":
                    open = false;
                    readResumed = false;
                    return null;
                case "isOpen":
                    return open;
                case "toString":
                    return "test-source";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }
    }

    private static final class SinkStub {

        private final Deque<WriteEvent> writes = new ArrayDeque<>();
        private final RecordingSetter<StreamSinkChannel> writeSetter = new RecordingSetter<>();
        private final RecordingSetter<StreamSinkChannel> closeSetter = new RecordingSetter<>();
        private final StreamSinkChannel channel;
        private int writeCalls;
        private int resumeWritesCalls;
        private int suspendWritesCalls;
        private int wakeupWritesCalls;
        private int bytesWritten;
        private boolean writeResumed;
        private boolean open = true;

        private SinkStub() {
            channel = (StreamSinkChannel) Proxy.newProxyInstance(
                    SinkStub.class.getClassLoader(),
                    new Class<?>[]{StreamSinkChannel.class},
                    this::invoke);
        }

        private StreamSinkChannel channel() {
            return channel;
        }

        private SinkStub write(int count) {
            writes.add(WriteEvent.count(count));
            return this;
        }

        private SinkStub consumeAll() {
            writes.add(WriteEvent.count(Integer.MAX_VALUE));
            return this;
        }

        private SinkStub failWith(IOException failure) {
            writes.add(WriteEvent.failure(failure));
            return this;
        }

        private SinkStub runtimeFailure(RuntimeException failure) {
            writes.add(WriteEvent.failure(failure));
            return this;
        }

        private Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            switch (method.getName()) {
                case "write":
                    writeCalls++;
                    if (args == null || args.length != 1 || !(args[0] instanceof ByteBuffer)) {
                        return 0;
                    }
                    WriteEvent event = writes.poll();
                    if (event == null) {
                        throw new AssertionError("No sink write result configured");
                    }
                    if (event.failure != null) {
                        throw event.failure;
                    }
                    ByteBuffer buffer = (ByteBuffer) args[0];
                    int count = Math.min(event.count, buffer.remaining());
                    buffer.position(buffer.position() + count);
                    bytesWritten += count;
                    return count;
                case "getWriteSetter":
                    return writeSetter;
                case "getCloseSetter":
                    return closeSetter;
                case "resumeWrites":
                    resumeWritesCalls++;
                    writeResumed = true;
                    return null;
                case "suspendWrites":
                    suspendWritesCalls++;
                    writeResumed = false;
                    return null;
                case "wakeupWrites":
                    wakeupWritesCalls++;
                    return null;
                case "isWriteResumed":
                    return writeResumed;
                case "close":
                    open = false;
                    writeResumed = false;
                    return null;
                case "isOpen":
                    return open;
                case "toString":
                    return "test-sink";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }
