    @Test
    void handleEventWhenDoneSuspendsWritesForSinkChannel() {
        Fixture fixture = new Fixture().sourceDone(true);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

