        listener.handleEvent(fixture.sourceChannel());
        assertEquals(1L, fixture.source.count("suspendReads"));
        assertEquals(1L, fixture.sink.count("suspendWrites"));
        assertEquals(1, fixture.pool.allocated.size());

        fixture.source.reset();
        fixture.sink.reset();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.sink.count("suspendWrites"), "done listener must suspend writes");
        assertEquals(1L, fixture.sink.count("isWriteResumed") + fixture.sink.count("resumeWrites")
                + fixture.sink.count("wakeupWrites"), "done listener must not resume or wake up writes");
        assertEquals(0, fixture.source.calls.size(), "sink notification must not touch the source");
        assertEquals(1, fixture.pool.allocated.size(), "no buffer must be allocated once the transfer is done");
    }

