        assertEquals(1L, fixture.source.count("suspendReads") + fixture.source.count("resumeReads"), "no extra resume/suspend");
        assertEquals(1, fixture.sink.writeSetter.setCount);
        assertSame(fixture.sinkListener, fixture.sink.writeSetter.get());
        assertEquals(1L, fixture.sink.count("wakeupWrites"), "the sink listener is woken up on completion");
        assertTrue(fixture.pool.allocated.get(0).isClosed(), "the drained buffer is released");

        fixture.source.reset();
        fixture.sink.reset();
        listener.handleEvent(fixture.sinkChannel());
        assertEquals(1L, fixture.sink.count("suspendWrites"), "the transfer must be marked as done");
    }

    @Test
    void handleEventCompletesAndSuspendsChannelsWhenSourceIsEofAndListenersAreNull() {
        Fixture fixture = new Fixture();
        fixture.read(buffer -> -1);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals(1L, fixture.source.count("suspendReads"), "null source listener means reads are suspended");
        assertEquals(1L, fixture.sink.count("suspendWrites"), "null sink listener means writes are suspended");
        assertEquals(0L, fixture.source.count("wakeupReads"));
        assertEquals(0L, fixture.sink.count("wakeupWrites"));
        assertEquals(0L, fixture.sink.countPrefix("write:"), "nothing was read so nothing is written");
        assertEquals(1, fixture.pool.allocated.size());
        assertTrue(fixture.pool.allocated.get(0).isClosed());
    }

    // -------------------------------------------------------------- failures

    @Test
    void handleEventClosesBufferAndNotifiesWriteExceptionHandlerOnWriteFailure() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        IOException failure = new IOException("write failed");
        fixture.write(buffer -> {
            throw failure;
        });
        List<Channel> handledChannels = new ArrayList<>();
        List<Throwable> handledFailures = new ArrayList<>();
        fixture.writeExceptionHandler((channel, exception) -> {
            handledChannels.add(channel);
            handledFailures.add(exception);
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1, handledFailures.size(), "the write exception handler must be invoked once");
        assertSame(failure, handledFailures.get(0));
        assertSame(fixture.sinkChannel(), handledChannels.get(0));
        assertTrue(pooledBuffer.isClosed(), "the pending buffer must be released on a write failure");
        assertEquals(0L, fixture.source.countPrefix("read:"), "no read is attempted after a write failure");
        assertEquals(0L, fixture.sink.count("resumeWrites"));
        assertEquals(0L, fixture.source.count("resumeReads"));

        fixture.sink.reset();
        listener.handleEvent(fixture.sinkChannel());
        assertEquals(1L, fixture.sink.count("suspendWrites"), "a failed transfer is marked as done");
    }

    @Test
    void handleEventClosesBufferAndNotifiesReadExceptionHandlerOnReadFailure() {
        Fixture fixture = new Fixture();
        IOException failure = new IOException("read failed");
        fixture.read(buffer -> {
            throw failure;
        });
        List<Channel> handledChannels = new ArrayList<>();
        List<Throwable> handledFailures = new ArrayList<>();
        fixture.readExceptionHandler((channel, exception) -> {
            handledChannels.add(channel);
            handledFailures.add(exception);
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals(1, handledFailures.size(), "the read exception handler must be invoked once");
        assertSame(failure, handledFailures.get(0));
        assertSame(fixture.sourceChannel(), handledChannels.get(0));
        assertEquals(1, fixture.pool.allocated.size());
        assertTrue(fixture.pool.allocated.get(0).isClosed(), "the allocated buffer must be released on a read failure");
        assertEquals(0L, fixture.sink.countPrefix("write:"));
        assertEquals(0L, fixture.sink.calls.size(), "the sink is not touched when a read fails");

        fixture.source.reset();
        listener.handleEvent(fixture.sourceChannel());
        assertEquals(1L, fixture.source.count("suspendReads"), "a failed transfer is marked as done");
    }

    // ------------------------------------------------------ buffered leftovers

    @Test
    void handleEventCompactsBufferedDataAndReadsIntoItForReadNotification() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.read(buffer -> {
            assertEquals(3, buffer.position(), "the leftover data must be kept at the start of the buffer");
            assertEquals(CAPACITY - 3, buffer.remaining(), "the read is performed after the leftover data");
            return 0;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals(0, fixture.pool.allocated.size(), "the existing buffer is reused");
        assertEquals(1L, fixture.source.count("read:0"));
        assertEquals(0L, fixture.sink.countPrefix("write:"));
        assertEquals(1L, fixture.sink.count("resumeWrites"), "pending data means writes are resumed");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.source.count("suspendReads"));
        assertFalse(pooledBuffer.isClosed(), "a partially filled buffer must be kept for the next event");
        assertEquals("abc", drain(pooledBuffer.getBuffer()));
        assertEquals(0, pooledBuffer.getBuffer().position());
        assertEquals(3, pooledBuffer.getBuffer().limit());
    }

    @Test
    void handleEventKeepsBufferedDataWhenSinkWriteReturnsZero() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.sink.count("write:0"), "the sink is written to once and reports back pressure");
        assertEquals(1L, fixture.sink.count("resumeWrites"), "writes are resumed as data is still pending");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.sink.count("suspendWrites"));
        assertFalse(pooledBuffer.isClosed());
        assertEquals("abc", drain(pooledBuffer.getBuffer()), "the unwritten data must survive the event");
    }

    @Test
    void handleEventDoesNotResumeChannelsThatAreAlreadyResumed() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abc");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        fixture.sink.writeResumed = true;
        fixture.source.readResumed = true;
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.sink.count("isWriteResumed"));
        assertEquals(0L, fixture.sink.count("resumeWrites"), "already resumed writes must not be resumed again");
        assertEquals(1L, fixture.source.count("isReadResumed"));
        assertEquals(0L, fixture.source.count("resumeReads"), "already resumed reads must not be resumed again");
        assertFalse(pooledBuffer.isClosed());
    }

    @Test
    void handleEventSuspendsReadsWhenBufferIsCompletelyFull() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "0123456789abcdef");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        fixture.write(buffer -> 0);
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(1L, fixture.source.count("suspendReads"), "a completely full buffer suspends reads");
        assertEquals(0L, fixture.source.count("resumeReads"));
        assertEquals(0L, fixture.source.countPrefix("read:"), "there is no room left to read into");
        assertEquals(1L, fixture.sink.count("resumeWrites"));
        assertFalse(pooledBuffer.isClosed());
        assertEquals(CAPACITY, pooledBuffer.getBuffer().remaining());
    }

    @Test
    void handleEventWritesRemainingDataBeforeCompletingWhenSourceIsDone() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "xyz");
        Fixture fixture = new Fixture().sourceDone(true).pooledBuffer(pooledBuffer);
        ByteArrayOutputStream written = new ByteArrayOutputStream();
        fixture.write(buffer -> {
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            written.write(data, 0, data.length);
            return data.length;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sourceChannel());

        assertEquals("xyz", new String(written.toByteArray(), StandardCharsets.UTF_8),
                "the buffered data must be flushed before completing");
        assertEquals(0L, fixture.source.countPrefix("read:"), "a finished source must not be read again");
        assertEquals(1L, fixture.source.count("suspendReads"));
        assertEquals(1L, fixture.sink.count("suspendWrites"));
        assertTrue(pooledBuffer.isClosed(), "the fully written buffer is released");
    }

    @Test
    void handleEventWritesUntilBufferIsDrainedWithPartialWrites() {
        FakePooledBuffer pooledBuffer = bufferContaining(CAPACITY, "abcd");
        Fixture fixture = new Fixture().pooledBuffer(pooledBuffer);
        ByteArrayOutputStream written = new ByteArrayOutputStream();
        fixture.write(buffer -> {
            int chunk = Math.min(2, buffer.remaining());
            byte[] data = new byte[chunk];
            buffer.get(data);
            written.write(data, 0, chunk);
            return chunk;
        });
        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener = fixture.listener();

        listener.handleEvent(fixture.sinkChannel());

        assertEquals(2L, fixture.sink.countPrefix("write:"), "the write loop continues while the sink accepts data");
        assertEquals("abcd", new String(written.toByteArray(), StandardCharsets.UTF_8));
        assertEquals(1L, fixture.sink.count("suspendWrites"), "an empty buffer suspends writes");
        assertEquals(1L, fixture.source.count("resumeReads"));
        assertTrue(pooledBuffer.isClosed());
    }

    // ------------------------------------------------------------- test doubles

    @FunctionalInterface
    interface ReadHandler {
        int read(ByteBuffer buffer) throws IOException;
    }

    @FunctionalInterface
    interface WriteHandler {
        int write(ByteBuffer buffer) throws IOException;
    }

    static final class Fixture {

        final FakePool pool = new FakePool(CAPACITY);
        final RecordingChannel source = new RecordingChannel();
        final RecordingChannel sink = new RecordingChannel();
        PooledByteBuffer pooledBuffer;
        ChannelListener<? super StreamSourceChannel> sourceListener;
        ChannelListener<? super StreamSinkChannel> sinkListener;
        ChannelExceptionHandler<? super StreamSinkChannel> writeExceptionHandler;
        ChannelExceptionHandler<? super StreamSourceChannel> readExceptionHandler;
        boolean sourceDone;

        Fixture pooledBuffer(FakePooledBuffer buffer) {
            this.pooledBuffer = buffer;
            return this;
        }

        Fixture sourceDone(boolean done) {
            this.sourceDone = done;
            return this;
        }

        Fixture read(ReadHandler handler) {
            source.readHandler = handler;
            return this;
        }

        Fixture write(WriteHandler handler) {
            sink.writeHandler = handler;
            return this;
        }

        Fixture sourceListener(ChannelListener<? super StreamSourceChannel> listener) {
            this.sourceListener = listener;
            return this;
        }

        Fixture sinkListener(ChannelListener<? super StreamSinkChannel> listener) {
            this.sinkListener = listener;
            return this;
        }

        Fixture writeExceptionHandler(ChannelExceptionHandler<? super StreamSinkChannel> handler) {
            this.writeExceptionHandler = handler;
            return this;
        }

        Fixture readExceptionHandler(ChannelExceptionHandler<? super StreamSourceChannel> handler) {
            this.readExceptionHandler = handler;
            return this;
        }

        StreamSourceChannel sourceChannel() {
            return (StreamSourceChannel) source.proxy(StreamSourceChannel.class);
        }

        StreamSinkChannel sinkChannel() {
            return (StreamSinkChannel) sink.proxy(StreamSinkChannel.class);
        }

        Transfer.TransferListener<StreamSourceChannel, StreamSinkChannel> listener() {
            return new Transfer.TransferListener<>(pool, pooledBuffer, sourceChannel(), sinkChannel(),
                    sourceListener, sinkListener, writeExceptionHandler, readExceptionHandler, sourceDone);
        }
    }

    static final class RecordingSetter<T extends Channel> extends ChannelListener.SimpleSetter<T> {

        int setCount;

        @Override
        public void set(ChannelListener<? super T> listener) {
            setCount++;
            super.set(listener);
        }
    }

    static final class RecordingChannel implements InvocationHandler {

        final List<String> calls = new ArrayList<>();
        final RecordingSetter<Channel> readSetter = new RecordingSetter<>();
        final RecordingSetter<Channel> writeSetter = new RecordingSetter<>();
        final RecordingSetter<Channel> closeSetter = new RecordingSetter<>();

        boolean readResumed;
        boolean writeResumed;
        boolean open = true;
        ReadHandler readHandler = buffer -> 0;
        WriteHandler writeHandler = buffer -> {
            int remaining = buffer.remaining();
            buffer.position(buffer.limit());
            return remaining;
        };

        private final Map<List<Class<?>>, Object> proxies = new HashMap<>();

        Object proxy(Class<?>... interfaces) {
            List<Class<?>> key = List.of(interfaces);
            return proxies.computeIfAbsent(key,
                    ignored -> Proxy.newProxyInstance(RecordingChannel.class.getClassLoader(), interfaces, this));
        }

        void reset() {
            calls.clear();
        }

        long count(String call) {
            return calls.stream().filter(call::equals).count();
        }

        long countPrefix(String prefix) {
            return calls.stream().filter(call -> call.startsWith(prefix)).count();
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            String name = method.getName();
            switch (name) {
                case "getReadSetter":
                    calls.add("getReadSetter");
                    return readSetter;
                case "getWriteSetter":
                    calls.add("getWriteSetter");
                    return writeSetter;
                case "getCloseSetter":
                    calls.add("getCloseSetter");
                    return closeSetter;
                case "suspendReads":
                    calls.add("suspendReads");
                    readResumed = false;
                    return null;
                case "resumeReads":
                    calls.add("resumeReads");
                    readResumed = true;
                    return null;
                case "wakeupReads":
                    calls.add("wakeupReads");
                    return null;
                case "isReadResumed":
                    calls.add("isReadResumed");
                    return readResumed;
                case "suspendWrites":
                    calls.add("suspendWrites");
                    writeResumed = false;
                    return null;
                case "resumeWrites":
                    calls.add("resumeWrites");
                    writeResumed = true;
                    return null;
                case "wakeupWrites":
                    calls.add("wakeupWrites");
                    return null;
                case "isWriteResumed":
                    calls.add("isWriteResumed");
                    return writeResumed;
                case "read":
                    if (args != null && args.length == 1 && args[0] instanceof ByteBuffer) {
                        int read = readHandler.read((ByteBuffer) args[0]);
                        calls.add("read:" + read);
                        return read;
                    }
                    return defaultValue(method.getReturnType());
                case "write":
                    int written = writeHandler.write((ByteBuffer) args[0]);
                    calls.add("write:" + written);
                    return written;
                case "flush":
                    return Boolean.TRUE;
                case "isOpen":
                    return open;
                case "close":
                    calls.add("close");
                    open = false;
                    return null;
                case "toString":
                    return "RecordingChannel";
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                default:
                    return defaultValue(method.getReturnType());
            }
        }

        private static Object defaultValue(Class<?> type) {
            if (type == boolean.class) {
                return Boolean.FALSE;
            } else if (type == byte.class) {
                return (byte) 0;
            } else if (type == short.class) {
                return (short) 0;
            } else if (type == int.class) {
                return 0;
            } else if (type == long.class) {
                return 0L;
            } else if (type == float.class) {
                return 0f;
            } else if (type == double.class) {
                return 0d;
            } else if (type == char.class) {
                return (char) 0;
            }
            return null;
        }
    }

    static final class FakePooledBuffer implements PooledByteBuffer {

        private final ByteBuffer buffer;
        private boolean open = true;
        private int closeCount;

        FakePooledBuffer(ByteBuffer buffer) {
            this.buffer = buffer;
        }

        @Override
        public ByteBuffer getBuffer() {
            return buffer;
        }

        @Override
        public void close() {
            open = false;
            closeCount++;
        }

        @Override
        public boolean isOpen() {
            return open;
        }

        boolean isClosed() {
            return !open;
        }

        int getCloseCount() {
            return closeCount;
        }
    }

    static final class FakePool implements ByteBufferPool {

        private final int capacity;
        final List<FakePooledBuffer> allocated = new ArrayList<>();

        FakePool(int capacity) {
            this.capacity = capacity;
        }

        @Override
        public PooledByteBuffer allocate() {
            FakePooledBuffer pooledBuffer = new FakePooledBuffer(ByteBuffer.allocate(capacity));
            allocated.add(pooledBuffer);
            return pooledBuffer;
        }

        @Override
        public ByteBufferPool getArrayBackedPool() {
            return this;
        }

        @Override
        public void close() {
        }

        @Override
        public int getBufferSize() {
            return capacity;
        }

        @Override
        public boolean isDirect() {
            return false;
        }
    }

    private static FakePooledBuffer bufferContaining(int capacity, String data) {
        ByteBuffer buffer = ByteBuffer.allocate(capacity);
        buffer.put(data.getBytes(StandardCharsets.UTF_8));
        buffer.flip();
        return new FakePooledBuffer(buffer);
    }

    private static String drain(ByteBuffer buffer) {
        ByteBuffer copy = buffer.duplicate();
        byte[] data = new byte[copy.remaining()];
        copy.get(data);
        return new String(data, StandardCharsets.UTF_8);
    }
}
